INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tobe & Friends Hookshot Escape', 'Tobe & Friends Hookshot Escape is a retro endless platformer, a return to arcade high score madness and a love letter to our childhood. Features 4 different characters (each with their own unique ability), 4 pixel worlds, over 20 equipments to unlock plus 5 leaderboards (one for each character and an additional one for the overall highscore).' FROM games WHERE igdb_id = 65325 ON CONFLICT (game_id, language_code) DO NOTHING;
