INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merlin: A Servant of Two Masters', 'Merlin: A Servant of Two Masters is a hidden-object adventure game for the Nintendo DS based on an episode of the Merlin television series. The story follows Merlin after he falls under Morgana’s influence, placing him at odds with Arthur and the knights of Camelot. Players assist Arthur and other characters by searching for hidden objects across multiple scenes and solving puzzles and mini-games in order to uncover what has happened to Merlin and prevent further harm.' FROM games WHERE igdb_id = 383335 ON CONFLICT (game_id, language_code) DO NOTHING;
