INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 3', 'Explore an island playground as stunningly beautiful as it is diverse – from mountain ranges to swampy grasslands and white sandy beaches. Fight your way through the island’s towns, temples, river ports and more. Encounter a diverse and realistic cast of characters, including one of Far Cry’s most notorious villains: Vaas Montenegro. Dive into this deep and enriching story where morals are questionable and hope is all but abandoned.' FROM games WHERE igdb_id = 529 ON CONFLICT (game_id, language_code) DO NOTHING;
