INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cases of Stolen Beauty', 'Journalist Eva Sanders has been sent to Rio de Janeiro for Carnival. After numerous strange events take place, she realizes she is being framed. Can you help uncover evidence in this hidden object game to restore her reputation?' FROM games WHERE igdb_id = 341084 ON CONFLICT (game_id, language_code) DO NOTHING;
