INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB 12: The Show', 'MLB 12 The Show is the latest release in a franchise has been the highest rated sports video game for the past 4 years. The Show enables consumers to immerse themselves in exhilarating baseball moments by delivering true-to-life gameplay, authentic franchise and season modes, and incredible detail not found in any other sports game. MLB 12 The Show builds on what has been delivered in previous franchise releases adding compelling features that bring unparalleled innovation and polish to the sports genre.' FROM games WHERE igdb_id = 7374 ON CONFLICT (game_id, language_code) DO NOTHING;
