INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Happy Fall', 'Join a cute family of Jelly and Ice Cream characters on an exciting journey. Drop safely between the platforms to fall down deeper and deeper. You still have to keep everyone safe from the mean flies, but this time you have a huge range of power ups to help you fight back. Collect all the characters by picking up the coins in the game, or you can use your coins to build up the power ups!' FROM games WHERE igdb_id = 274388 ON CONFLICT (game_id, language_code) DO NOTHING;
