INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shining-blade', 65348, '2012-03-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49u9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scevpa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Blade', 'This is a Japan-only game in the Shining franchise. The game''s battle system is called "Concerto", and is a strategic real time battle system similar to the ones found in Sakura Wars and Valkyria Chronicles. The player make use of swords, bows and magic in a battle system that places importance on character cooperation—hence the name "Concerto". The player forms a party of up to five for battle. The game will have damage based on character position, and items collected upon defeating enemies. The songstresses are special members of the player''s battle party. By performing their magic song, they can achieve various effects on battle—blocking enemies from moving, increasing characters'' move count, making hasten the party''s pace. Some songs can even be used for attack. Using the songs requires Mana Energy. The game also has inter-character relationships. Depending on the player''s selections during event scenes, movements and usage of group skills during battle, the characters'' relationships will change.' FROM games WHERE igdb_id = 65348 ON CONFLICT (game_id, language_code) DO NOTHING;
