INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game Dev Tycoon', 'In Game Dev Tycoon you replay the history of the gaming industry by starting your own video game development company in the 80s. Create best selling games. Research new technologies and invent new game types. Become the leader of the market and gain worldwide fans.' FROM games WHERE igdb_id = 2599 ON CONFLICT (game_id, language_code) DO NOTHING;
