INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Sora no Kiseki FC Kai - HD Edition', 'A remaster of the PSP version of the first installment in the series, serving as the beginning to the Liberl arc and the series as a whole, with enhanced graphics, cross-save with the PSP version and extras like PS3 themes, music, calendars and more. The game follows protagonists Estelle Bright and her adopted brother Joshua, who journey through the country of Liberl to train to become senior Bracers, members of a non-government multinational organization that acts to keep the peace and protect civilians.' FROM games WHERE igdb_id = 136859 ON CONFLICT (game_id, language_code) DO NOTHING;
