INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vritra', 'Throw down a challenge to all the 80s and 90s gamers. Get back the enthusiasm you had once! Control the dragon and the vajras, and destroy the evil Dragon Emperor "VRITRA"! Awesome graphics, powerful sound effects and amazing controls. This ultimate 2D shooter is a step forward in the history of the shooting games!' FROM games WHERE igdb_id = 125651 ON CONFLICT (game_id, language_code) DO NOTHING;
