INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Dome', 'Death Dome is a post-apocalyptic action game developed by Griptonite Games and published by Glu Mobile, released for iOS and Android on October 10, 2012. Set in a quarantined city ravaged by a deadly virus, players take control of Phoenix, a genetically enhanced warrior, battling monstrous Behemoths in brutal one-on-one combat. The game features swipe-based fighting mechanics, upgradeable weapons, and a gritty sci-fi atmosphere reminiscent of Infinity Blade.' FROM games WHERE igdb_id = 344219 ON CONFLICT (game_id, language_code) DO NOTHING;
