INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missing Parts: The Tantei Stories Complete', 'This work is a PSP version of the the Missing Parts stories released on Dreamcast and PS2 from 2002 to 2004. It is a mystery adventure game set in the local city of Wenhu, where Detective Kyosuke Shinjo uses information gathering and analytical power to confront difficult cases. The PSP version contains all six episodes of scenarios, as well as new scenarios. An additional scenario will be a story where you can enjoy episodes that were not mentioned in the main part and new aspects of the characters.' FROM games WHERE igdb_id = 64630 ON CONFLICT (game_id, language_code) DO NOTHING;
