INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Containment: The Zombie Puzzler', 'Containment: The Zombie Puzzler is an action puzzle game like you’ve never seen before. The goal of Containment is to surround zombies with survivors of the same color. But watch out for the zombies—they''ll fight back by infecting the survivors in the street. Through the game''s pulse-pounding campaign and multiple survival modes, you''ll use your wits, items you find you along the way, and even the town around you to contain the zombie outbreak.' FROM games WHERE igdb_id = 15163 ON CONFLICT (game_id, language_code) DO NOTHING;
