INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carmen-sandiego-adventures-in-math-the-great-gateway-grab', 51080, '2012-03-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pvv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/enwlkpfwuodpzdfpschj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carmen Sandiego Adventures in Math: The Great Gateway Grab', 'Carmen Sandiego is back and only you can foil her V.I.L.E plans. Travel the globe, solve brain-twisting math puzzles, and catch the villain behind the Great Gateway Grab. Crack the case of the Great Gateway Grab in single-player Story Mode. Perfect your math skills in single-player Practice Mode. Challenge your friends and family to solve math puzzles against the clock in Multiplayer Mode. In Carmen Sandiego Adventures in Math: The Great Gateway Grab, you practice your math skills and use them to fight crime. Ideal for grades 4-5, math topics include arithmetic, logic puzzles, fractions and much more!' FROM games WHERE igdb_id = 51080 ON CONFLICT (game_id, language_code) DO NOTHING;
