INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hallowed Legends: Templar - Collector''s Edition', 'Hallowed Legends: Templar is the second title of the Hallowed Legends series. This is a special Collector''s Edition release full of exclusive extras you won’t find in the standard version. The Collector’s Edition includes: - Bonus gameplay - Integrated Strategy Guide - Wonderful Wallpapers' FROM games WHERE igdb_id = 376584 ON CONFLICT (game_id, language_code) DO NOTHING;
