INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy Crush Saga', 'Candy Crush Saga is a free-to-play match-three puzzle video game released by King as a variation of their browser game Candy Crush. In the game, players complete levels by swapping colored pieces of candy on a game board to make a match of three or more of the same color, eliminating those candies from the board and replacing them with new ones, which could potentially create further matches. Boards have various goals that must be completed within a fixed number of moves, such as collecting a specific number of a type of candy.' FROM games WHERE igdb_id = 5636 ON CONFLICT (game_id, language_code) DO NOTHING;
