INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes Consulting Detective: The Case of the Tin Soldier', 'Inspector Smythe from Scotland Yard has informed Watson and me of the murder of General Armstead, a Tontine ticket holder. Something about this case intrigues me. Perhaps it ís that the General was about to publish a scintillating addendum to his infamous book on treasure.' FROM games WHERE igdb_id = 35062 ON CONFLICT (game_id, language_code) DO NOTHING;
