INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes and the Mystery of the Frozen City', 'When a mysterious snowstorm falls on London, so cold that even the Thames is starting to freeze, Sherlock Holmes, the most astute detective of all time, is called in to investigate. Explore amazing environments, meet and interrogate many colorful characters, and examine objects and clues in order to discover the evidence that will help solve this incredible case. Many original puzzles and brain-teasers will put your skills to the test during your investigation, while you unveil the truth behind the Mystery of the Frozen City!' FROM games WHERE igdb_id = 47657 ON CONFLICT (game_id, language_code) DO NOTHING;
