INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Royale: Ninja Action RPG', 'Fight! Quest! Heist! One million downloads can’t be wrong. Ninja Royale, is burning up the charts with over 27,000 five-star reviews. Battle formidable foes with combos and cunning moves, strategically upgrading and fusing weapons. Explore multiple worlds packed with hundreds of items and rewards, and join a near-constant stream of exciting events that feature raid bosses, arena battles and (literally) shots in the dark. Greet other players with friendly messages, or ambush them and steal their treasure!' FROM games WHERE igdb_id = 339877 ON CONFLICT (game_id, language_code) DO NOTHING;
