INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K13', 'With more than 5 million copies sold worldwide and more than 25 Sports Game of the Year awards won, NBA 2K12 was another monster release for the biggest NBA video game simulation franchise in the world. This year, 2K Sports has joined forces with the legendary JAY Z as Executive Producer to transcend sports video games and take virtual hardwood to the next level. Featuring an enhanced MyCAREER mode and all-new gameplay features, NBA 2K13 will let gamers pit the best players in NBA history against the new dynasty of talent, including the much-debated matchup between the 2012 U.S. Men''s National Team and the 1992 "Dream Team."' FROM games WHERE igdb_id = 5058 ON CONFLICT (game_id, language_code) DO NOTHING;
