INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silent-hill-downpour', 487, '2012-03-13', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc897w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: Downpour', 'Silent Hill: Downpour is the eighth Silent Hill video game installment and the last fully-released video game in the series. Just like its predecessors, Downpour combines exploring abandoned surroundings, talking to characters, and solving puzzles, set against a slow, psychological horror theme. Different from the previous game Silent Hill: Shattered Memories is the return of combat. The player often has to fight off monsters using a variety of weapons, but he can carry only one melee and one ranged weapon who can deteriorate over time. Entirely new to the series is the introduction of a weather system: there is a full day and night cycle and rain often warns the player of danger that is approaching. It is possible to hide until the weather becomes better again.' FROM games WHERE igdb_id = 487 ON CONFLICT (game_id, language_code) DO NOTHING;
