INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-libra-2', 25539, '2012-09-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/r5ehyx0zdrj2trxonkd6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rwxcc5eavhzmf6a2udfr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Libra 2', 'Small is beautiful. Those just might be the most fun tiny ships you will ever command!  Play as the commander of "Libra II", the newest state of the technological art space carrier and take revenge on Alien Invaders that took over your home world. This time you will bring the fight to them and let them taste your power.  Build a variety of crafts, conquer planets and space stations and travel the universe. You will face a single player campaign filled with exciting battles depicted with unique art style. Upgrade your ships and combine them into unstoppable fleets.  Blue Libra 2 introduces multiplayer combat for up to 4 players in skirmish mode. You can play via gamecenter, directly with a bluetooth or over wifi or the internet. (The available multiplayer options may vary depending on your network setup and Operating System version). Blue Libra II brings improved graphics, more immersive gameplay and extended economy with more decision making. Game features new ships, unique for both races and over 30 single player maps.  Blue Libra 2 uses retina display (if available) for enhanced combat graphics. If retina display is not available, it''ll automatically switch to regular display.' FROM games WHERE igdb_id = 25539 ON CONFLICT (game_id, language_code) DO NOTHING;
