INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal', 'Twisted Metal is a vehicle combat video game developed by Eat Sleep Play and published by Sony Computer Entertainment for the PlayStation 3. It is a reboot of the Twisted Metal franchise. The game was originally planned to be released in October 2011 but was delayed to early 2012.' FROM games WHERE igdb_id = 5416 ON CONFLICT (game_id, language_code) DO NOTHING;
