INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extrapower Star Resistance', 'An indie shoot ''em up from doujin team Lucky Lamp that takes place in the Extrapower universe. Prior to the events of Attack of Darkforce, Sharkungo and Force Star respond to a report that Dark Force is attacking the Shakun Star itself. Traverse across 6 stages from the Satellite Mesa to the heart of the royal capital city to fight through swarms of enemies and repel the Dark Force attack on Sharkungo''s homeworld.' FROM games WHERE igdb_id = 191696 ON CONFLICT (game_id, language_code) DO NOTHING;
