INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shinshou-sange-chiru-hana', 384248, '2012-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob7uf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc115is.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinshou Sange: Chiru Hana', 'A place that is here and not here. Once the water surface looks blue, there''s no going back. An older sister who can see the future and a girl called the Grim Reaper. Is what we see really the truth? Or is what we cannot see the truth? Produced by our circle, Scattering flowers ~Chiruhana~ Reconstructing the second chapter of Renge ~Renka~Sange, This work includes a final chapter.' FROM games WHERE igdb_id = 384248 ON CONFLICT (game_id, language_code) DO NOTHING;
