INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crosswords Plus', 'The Crosswords Plus game is chock full of puzzles to help you exercise your word power. The professionally designed crossword puzzles cover all difficulty levels-from Easy to Expert. Discover fun ways to work your wordsmithing skills beyond typical crossword puzzles with epic Giant Crosswords, and other modes like Word of the Day, Wordsearch, and Anagrams. Download a constant flow of new puzzles via SpotPass at no additional charge, and share bonus puzzles with other players via StreetPass.' FROM games WHERE igdb_id = 10230 ON CONFLICT (game_id, language_code) DO NOTHING;
