INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Piggies', 'Bad Piggies is a puzzle video game and a spin-off to Angry Birds. Unlike previous games in the series, in this entry the player controls the pigs, building devices that travel on land and air to find pieces of a map to find the Angry Birds'' eggs The objective of the game is to build a contraption that transports the pig from a starting point to the finish line, usually indicated by a map. Such contraptions are made of wood and iron as well as other objects such as wheels, soda bottles, umbrellas (to increase air resistance), motors, fans, TNT, and balloons.' FROM games WHERE igdb_id = 19902 ON CONFLICT (game_id, language_code) DO NOTHING;
