INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cytus', '200 songs and 400 variations, including many from famous composers around the world. Beautiful hand-drawn art style. Easy, intuitive Active Scan Line system and 3 types of notes. Different display modes allow player-friendly previewing of notes. Strong beat and rhythms provide satisfying feedback for taps. More than 9 difficulty levels for more fun and challenges. Various music genres: POP, JAZZ, TRANCE, HARDCORE, DRUM ''N BASS and much more.' FROM games WHERE igdb_id = 27026 ON CONFLICT (game_id, language_code) DO NOTHING;
