INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: Revelations', 'Resident Evil: Revelations is a survival horror game that restores elements of the series'' nature, as opposed to the survival action of Resident Evil 5. The game features a single-player mode where the player must complete a series of episodes that involve solving puzzles and defeating enemies, and a multiplayer mode where players may fight their way through altered single-player scenarios.' FROM games WHERE igdb_id = 978 ON CONFLICT (game_id, language_code) DO NOTHING;
