INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moon-breakers', 16350, '2012-04-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/c3v76r1fwmvnntslqwm2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/puk8og8sv8essg2qucya.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon Breakers', 'Moon Breakers is a free to play, multi-player 3D space combat game set in an alternate WWII-inspired future. As either a Government or Pirate pilot, take to the stars in single-seat starfighters and engage in epic dogfights for Helium-3 around the galaxy. A modern multi-player take on the classic space combat genre of the 1990''s, Moon Breakers delivers thrilling gameplay with simple controls that will have you flying and shaking bandits off your six in minutes. Coupled with a bold, retro-futuristic art style, amazing music by Bear McCreary (Battlestar Galactica, The Walking Dead) and a variety of ships to unlock and upgrade, Moon Breakers is pure space combat awesome. Sign up, climb in and get ready for launch... there are fortunes to be made.' FROM games WHERE igdb_id = 16350 ON CONFLICT (game_id, language_code) DO NOTHING;
