INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Staggering Beauty', 'Staggering Beauty is a game that pushes the boundaries of interactive art. In Staggering Beauty, you are greeted by a simple black, worm-like creature on your screen. As you move the cursor, the creature responds with fluid, hypnotic movements. The more you move the cursor, the more intense the creature''s reactions become. It''s a dance of movement and color that creates a surreal and immersive experience.' FROM games WHERE igdb_id = 337136 ON CONFLICT (game_id, language_code) DO NOTHING;
