INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings Online: Riders of Rohan - Heroic Edition Live', 'In The Lord of the Rings Online, join the world''s greatest fellowship of players in the faithful online re-creation of J. R. R. Tolkien''s legendary Middle-earth. From the crumbling, shadowed ruins of Weathertop to the ageless, golden wood of Lothlórien, immerse yourself in Middle-earth as you have never seen it before. Visit the peaceful, verdant fields of the Shire, brave the dark depths of the Mines of Moria, and raise a pint at the Prancing Pony in Bree!' FROM games WHERE igdb_id = 95570 ON CONFLICT (game_id, language_code) DO NOTHING;
