INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 2', 'An HD remaster of Devil May Cry 2, first made available in "Devil May Cry HD Collection." Devil May Cry 2 takes place many years after the first game. This installment introduces the ability to run along walls, the Rain Storm ability, and others, giving Dante even more freedom to defeat enemies in style. You can also play as the new character, Lucia, who uses speed as a weapon against enemies, as opposed to Dante who relies on power. The bonus mode, Bloody Palace, also makes its first appearance here.' FROM games WHERE igdb_id = 222655 ON CONFLICT (game_id, language_code) DO NOTHING;
