INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Gear 3', 'The long awaited sequel to Battle Gear 2 is here! Get ready for the fight of your life! Battle Gear 3 takes the familiar formula from Battle Gear 2 and improves upon it by adding more units, more strategy, and a greater diversity of upgrades! The whole point of the game is to conquer the world one country at a time by carefully managing your troops! There are tons of upgrades and leveling up to do! How far can you get in this exciting strategy game? Good luck!' FROM games WHERE igdb_id = 286628 ON CONFLICT (game_id, language_code) DO NOTHING;
