INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo 4: Limited Edition', 'Contents: A steel façade case with a UNSC device stencilled on it A redeemable code for the Infinity Actual Kit War Games Map Pass Recruit Prime armor skin Prime emblem Assault Rifle Prime weapon skin All eight Specializations unlocked immediately after reaching SR-50 Cryo-Chamber Avatar prop Recruit Armor Avatar clothes UNSC Infinity Briefing Packet, which includes Mjolnir Armor schematics, weapon information, and a layout of the indoctrination of the SPARTAN-IVs 90-minute extended edition of Halo 4: Forward Unto Dawn accessible through Halo Waypoint Bonus content providing backstory on characters and stories in Halo 4: Forward Unto Dawn Special featurette: Making of Halo 4: Forward Unto Dawn Special featurette: Bringing Gaming to Reality' FROM games WHERE igdb_id = 45148 ON CONFLICT (game_id, language_code) DO NOTHING;
