INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Drive ATS', 'Train Drive ATS enables players to drive a train following signals and based on precise physics calculation while other trains run simultaneously according to timetables. There are 37 sets of Tobu trains and 7 of others running on lines of some 50 kilometers. You are to drive precisely and safe. The ATS game replicates actual operations of switch rails, signals and crossing gates.' FROM games WHERE igdb_id = 175860 ON CONFLICT (game_id, language_code) DO NOTHING;
