INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: Shiny Festa - Honey Sound', 'The Idolmaster: Shiny Festa is a series of three Japanese rhythm video games. The games are part of The Idolmaster series of games, and were originally released as Honey Sound, Funky Note, and Groovy Tune. They were the first games in the series to be localized into English. The gameplay in Shiny Festa eschews the simulation format of previous Idolmaster games, and instead features a rhythmic gameplay in which the player times the presses of buttons to the rhythm of the songs and a predetermined pattern displayed on the screen.' FROM games WHERE igdb_id = 42796 ON CONFLICT (game_id, language_code) DO NOTHING;
