INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter X Games SnoCross', 'SnoCross is the latest racer from Raw Thrills. A 42″ LCD panel for HD graphics and a motion seat allows players to feel like they are part of the action. SnoCross has 6 snowmobile racers, 6 killer sleds, and insane custom upgrades. Plus travel the world by riding on 7 intense tracks in France, Antarctica, China, Alaska, Washington D.C., Moscow and Colorado. This game is officially licensed from ESPN and racers are able to perform the same sick tricks as seen in the X Games. Huge airtime gives you even more time to try crazy tricks. Throw snowballs at your opponents to battle for the lead. You can also share your scores to Facebook via personalized QR codes.' FROM games WHERE igdb_id = 125782 ON CONFLICT (game_id, language_code) DO NOTHING;
