INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rushing Alice', 'Rushing Alice is an action running game where you play as Alice who travels the mysterious scenes with adventures in order to find the way home, you can also collect the coins and gems laying around. You can run, jump, air hike, fly, smash obstacles, and use items in the game to challenge each endless stage. The coins and gems you collected in the game will be exchanged to points which you can use to buy avatar to make Alice more beautiful or buy items that can make game much easier...and of course, you can also buy points as an in-app purchase in the game shop.' FROM games WHERE igdb_id = 200116 ON CONFLICT (game_id, language_code) DO NOTHING;
