INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Age: Continental Drift', 'Scrat''s nutty pursuit of the accursed acorn, which he''s been after since the dawn of time, has world-changing consequences - a continental cataclysm that triggers the greatest adventure of all. Join Scrat, Manny, Diego and Sid on a wild journey through 13 levels spread across 5 icy environments.' FROM games WHERE igdb_id = 282576 ON CONFLICT (game_id, language_code) DO NOTHING;
