INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burn-the-corn', 254345, '2012-06-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nmj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn3ex.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burn the Corn', 'Be aware! Evil Moisture will send many Water Babies to stand in your way! These minions from the Realm of Moisture have the power to nature your Magic Flame! You should demonstrate your skill by moving around it gracefully while turning the baby corns into delicious popcorn! There are times when the anxious baby corns burst out all at once! This is the moment where you can use some help from your powerful allies! The Fire Warrior can combine with your Magic Flame to strengthen your power while the Time Wizard can slow down time to give you some breathing room. You will discover many more exciting elements and learn how to use them to your advantage throughout this magical journey! Now! Let us work together to help the baby corns to make their dreams come true!!' FROM games WHERE igdb_id = 254345 ON CONFLICT (game_id, language_code) DO NOTHING;
