INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: Fall of Cybertron', 'Transformers: Fall of Cybertron transports you to the final days of the planet Cybertron where you will experience the darkest hours of the apocalyptic war between the Autobots and Decepticons. Embark on an adrenaline-fueled journey through a wide range of missions and massive environments designed around each character''s unique abilities. Fight through both sides of the most epic battles leading to their legendary exodus from their homeworld. In addition, players experience action in the form of new Transformer bot types Combaticons, Insecticons, and Dinobots.' FROM games WHERE igdb_id = 8361 ON CONFLICT (game_id, language_code) DO NOTHING;
