INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pazuru-in-airou', 65177, '2012-07-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yt7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scutm0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pazuru in Airou', 'Airu village has been rather quiet these days, and the elder is feeling lonely. To bring energy and activities back to the village, he uses the gem stones the Airus found in the mines to create a puzzle game. Welcome to the puzzle festival. The victor is getting his wish granted, so all the cats and even some of the monsters, such as Jingaoh and Iiankuk drop everything that they are doing to play. The rules are simple, just line up the gem stones around the bomb and blast them away before the screen chokes up. Every time you blast the stones away, you''ll get a chance to send your opponents the annoying Donguri blocks. This is the chance where even the smallest of cats can defeat the big bad dragon.' FROM games WHERE igdb_id = 65177 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 65177 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
