INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monique: Passion Hôtesse de Caisse', 'Humorous and deliberately bad simulation of the daily life of a cashier. Scan them all! Monique: Passion Hôtesse de Caisse is a unique simulation that puts you, shower in hand, in various situations where speed and dexterity are essential to satisfy the customer and your boss!' FROM games WHERE igdb_id = 203076 ON CONFLICT (game_id, language_code) DO NOTHING;
