INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Life', 'Embark on the adventure of your dream life as you craft, cast, fish, mine, battle and explore like never before. With the innovative Life system, your choices don’t just upgrade characters—they help shape your journey. Explore a huge fantasy landscape beside surly dark paladins, slick pirate captains, regal princesses, and others who share your taste for the unknown.' FROM games WHERE igdb_id = 6770 ON CONFLICT (game_id, language_code) DO NOTHING;
