INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Beat', 'Magical Beat remixes the puzzle genre by adding in a beat! Drop colored blocks in a match-3 style to the background music''s rhythm with perfect timing to send blocks to your opponent''s screen. Charming 8-bit characters and menus guide you through stages with different BPMs for unique challenges and combo possibilities. Magical Beat features an original Vocaloid soundtrack created by Nico Nico celebrity and prolific sound creator Kikuo.' FROM games WHERE igdb_id = 52549 ON CONFLICT (game_id, language_code) DO NOTHING;
