INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Heights', '"Dream Heights" is a mobile game developed by Zynga where players build their own skyscraper by adding different floors with stores, restaurants, apartments, and more, where the goal is to create a thriving tower by managing your residents and businesses within it; it allows players to customise their tower, connect with friends, and even outbuild famous landmarks like the Statue of Liberty.' FROM games WHERE igdb_id = 333053 ON CONFLICT (game_id, language_code) DO NOTHING;
