INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brain-age-concentration-training', 20884, '2012-07-28', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n12.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4qa6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brain Age: Concentration Training', 'Brain Age is back with all-new devilishly difficult brain-training exercises designed by world-famous brain researcher Dr. Ryuta Kawashima. The modern mind has numerous devices to stay connected (e.g. laptops, smart phones, tablets), and these distractions have led to an information overload making it difficult to stay focused on specific tasks. Brain Age: Concentration Training offers newly designed training exercises to combat this information addiction. By spending at least five minutes a day, these exercises will challenge players with activities to help improve their concentration skills and the ability to access their short term memory. The new Devilish Training exercises dynamically increase or decrease in difficulty based on your real-time results to help consistently train players at the limit of their abilities. Beyond the Devilish Training, there are additional new and classic puzzles for every purpose, whether to challenge one''s concentration or math skills or provide relaxation activities to give the brain a break.' FROM games WHERE igdb_id = 20884 ON CONFLICT (game_id, language_code) DO NOTHING;
