INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sorcery', 'Sorcery is a magical fantasy adventure for the PlayStation 3 that transforms your Move controller into an incredible magic wand. The Nightmare Queen terrorizes the countryside, and only one of the fabled Sorcerers can stop her. Combine ancient, primal spells of the old world into devastating attacks as you battle the forces of darkness. Can you become a Sorcerer and save our world before it is plunged into Nightmare?' FROM games WHERE igdb_id = 20114 ON CONFLICT (game_id, language_code) DO NOTHING;
