INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Book of Unwritten Tales: The Critter Chronicles', 'The Critter Chronicles tell the story of how adventurer Nate Bonnett and Critter, his hairy sidekick, first met, all set before their appearance in Wilbur''s and Ivo''s adventure in The Book of Unwritten Tales. Enjoy a thrilling and hilarious point-and-click adventure in the fantasy world of Aventasia. Travel from the Northlands to the Mage''s Tower of Seastone and experience a story that offers tremendous fun for seasoned players of "The Book of Unwritten Tales" and newcomers alike.' FROM games WHERE igdb_id = 7661 ON CONFLICT (game_id, language_code) DO NOTHING;
