INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boutique Boulevard', 'It''s time to upgrade clothing stores and impress customers. Hire staff, pick clothes, and personalize your store with hundreds of decorations. Experiment with fabric and colors to discover new clothing. Train your staff to improve their skills in greeting, sales, and more.' FROM games WHERE igdb_id = 341069 ON CONFLICT (game_id, language_code) DO NOTHING;
