INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moshi Monsters: Moshlings Theme Park', 'Moshi Monsters: Moshlings Theme Park, developed by Black Lantern Studios, invites players to restore the legendary Moshi theme park to its former glory. Players progressively unlock six zones by successfully building attractions and rescuing the scattered Moshlings (adorable, itty bitty pets for your pet monster). Users of the Nintendo 3DS can also interact with other Nintendo 3DS players via the StreetPass feature and play cool games to bring the Moshlings to life in a whole new dimension. Moshi Monsters: Moshlings Theme Park marks the first time fans can interact with beloved characters via 3D technology and introduces players to a brand new, exclusive Moshling that can transfer across platforms to the online world.' FROM games WHERE igdb_id = 47658 ON CONFLICT (game_id, language_code) DO NOTHING;
