INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('math-blaster-hyperblast-2-hd', 93652, '2012-04-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bf5lggclmmyqlw9vylpt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x97hnpxjam01ysu1gx4s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Math Blaster HyperBlast 2 HD', 'From the makers of the award winning Math Blaster series! Over 20 years making math fun!  Hop on your HyperCycle and discover math facts like you’ve never seen them before! Race through levels shooting and dodging fast-flying obstacles to reach the Alien Boss! Use your math skills and smarts to battle and defeat the Alien Boss and unlock new weapons, ammo and more levels!  Reviews:  &9733; "Most importantly, this "edutainment" offering makes math fun by combining fast-action shooting sequences with elementary-level math problems." - USA Today  &9733; "The fast pace of the tunnels and obstacles adds excitement to the game and breaks up the Math practice." - The iPhone Mom  &9733; "I was instantly struck by how the math equations are programmed in to be a natural part of the game and not school like at all. If you know you’ll be spending time in the car this summer, Math Blaster HyperBlast is worth picking up." - Play That Now 
