INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('papas-pancakeria', 142945, '2012-03-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jzg.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Pancakeria', 'Rise and Shine with Papa''s Pancakeria! After searching high and low for your pet, you get a surprise call from Papa Louie. He''s been taking care of your pet at his latest restaurant, Papa''s Pancakeria. You quickly drive to Maple Mountain only to find your pet and a note from Papa Louie. Soon you find yourself knee deep in batter as you try to run the shop until Papa Louie returns. This latest game features pancakes, waffles and french toast along with a variety of new and returning customers in search of the best breakfast around. The time-management and hands-on gameplay of the series is back, with new challenges related stacking, arranging toppings and pouring syrup. Closers, badges, and tons of furniture are back and better than ever. New to the series, is a traveling game-show hosted by the Great Foodini! He stops by at the end of every day with a new mini-game to play. However Foodini only accepts special tickets that are earned throughout the day. Each ticket gives you a chance to play his daily game and possibly win over 95 unique prizes. Also new to the series is a very special Drink Station that can be unlocked that will add to the growing challenge of juggling your customers orders.' FROM games WHERE igdb_id = 142945 ON CONFLICT (game_id, language_code) DO NOTHING;
