INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Farm', 'Family Farm is an online farming game that allows players to build and develop their own farm using intuitive mechanics and friendly graphics.Starting with a small farm, players need to take care of their farms through planting and harvesting crops, feeding animals, and constructing machines.' FROM games WHERE igdb_id = 322141 ON CONFLICT (game_id, language_code) DO NOTHING;
