INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Rampage', 'Dungeon Rampage is an action MMO. Players can unlock and play different characters in Diablo-style combat, utilize powerful weapons, and enable various character skins for increased customization. Bash, stab, cook, and shock enemies into submission as you explore random maps alone, with friends, or with other members of the community in this fast-paced dungeon crawler.' FROM games WHERE igdb_id = 142975 ON CONFLICT (game_id, language_code) DO NOTHING;
