INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PlayStation All-Stars Battle Royale', 'Playstation All-Stars Battle Royal is a cross over fighting game featuring (mostly exclusive) iconic characters from various Playstation franchises. Each stage also feature prominent setting from other franchises. Playable characters are: Big Daddy (Bioshock) Cole MacGrath (Infamous) Colonel Radec (Killzone) Dante (DMC) Emmett Graves (Starhawk) (DLC content) Evil Cole McGrath (Infamous) Fate Princess (Fat Princess) Heihachi Mishima (Tekken) Isaac Clarke (Dead Space) (DLC content) Jak and Daxter (Jak and Daxter) Kat (Gravity Rush) (DLC content) Kratos (God of War) Nariko (Heavenly Sword) Nathan Drake (Uncharted) Parappa (Parappa the rapper) Raiden (Metal Gear Revengeance) Ratchet and Clank (Ratchet and Clank) Sackboy (Little Big Planet) Sir Daniel Fortesque (MediEvil) Sly Cooper (Sly Cooper) Spike (Ape Escape) Sweet Tooth (Twisted Metal) Toro Inoue (Doku Demo Issyo) Zeus (God of War) (DLC content)' FROM games WHERE igdb_id = 7390 ON CONFLICT (game_id, language_code) DO NOTHING;
