INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Ultimate Ninja Storm Generations', 'The title will power the series into the future by revolutionizing online play and ramping up the number of playable and support characters far beyond any NARUTO game in the wildly popular franchise. Players will compete in a variety of online battle modes with their favorite NARUTO characters, including Naruto and Sasuke. NARUTO fans have been waiting to see more of Zabuza and Haku since the launch of the original Manga, and now they will have their chance!' FROM games WHERE igdb_id = 7100 ON CONFLICT (game_id, language_code) DO NOTHING;
