INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('littlebigplanet-karting', 8186, '2012-11-06', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f3a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/samwg7nwnbs4mmpyd9qt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LittleBigPlanet Karting', 'Give full throttle to your imagination and join Sackboy and Sackgirl on the starting grid for a kart racing adventure like no other. Fire up your engines, jump behind the steering wheel and take on your friends and foes in breathtakingly unpredictable battles through an ever-changing world of content. Are you ready? LittleBigPlanet Karting combines the excitement and fun of a racing game with the ability to create any race you can imagine. Take advantage of simple and powerful creation tools to easily build your own tracks, design unique power-ups or customise your karts. Want to race a boxing glove through a land made of cheese? And then fire pizzas from your kart? You got it. Just watch out for those skull shaped hovercrafts. And flaming snakes. And whatever else is out there... Battle your friends online via PlayStation Network or in the same room using the split-screen mode, complete challenges or dive into the community to discover new player-created courses. No two tracks are ever the same, so you will never run out of new places to do battle. Race the unexpected and leave the real world in the dust!' FROM games WHERE igdb_id = 8186 ON CONFLICT (game_id, language_code) DO NOTHING;
