INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('re-birth-colony-lost-azurite', 60049, '2012-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv5q7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Re:birth Colony -Lost Azurite-', 'Five hundred years ago, the 5th star rain plunged the world into a deep winter, forcing humans to flee underground, under the sea or in man-made structures called arcologies. At first they waited for the day when the Earth would return to normal, but soon they lost interest in the outside world and were content living in their miniature peaceful worlds. The arcology Aquarius was founded as an international research institution on a man-made island, but now it is a segregated city with distinct rich and poor areas. Souji was an orphan living on the edge of the poor area of town. He owed his life to a blue-haired woman who saved him and his sister Ruri, but one day she disappeared. Helpless to save her, Souji vowed to become stronger. One day, a girl appeared before him. She looked exactly like the woman who disappeared and also had the same name – Azurite.' FROM games WHERE igdb_id = 60049 ON CONFLICT (game_id, language_code) DO NOTHING;
