INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mass-effect-3-n7-collectors-edition', 45180, '2012-03-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bxq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ij4cr5p7v7ev3tm8jdol.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mass Effect 3: N7 Collector''s Edition', 'This limited package includes: - Premium metal case featuring commemorative artwork of Commander Shepard - 70-page hardbound art book featuring hundreds of illustrations from the BioWare development team - Limited edition Mass Effect comic by Dark Horse Comics with unique cover artwork - Fabric N7 patch - 4x6 lithographic print featuring a piece of artwork - A full collection of exclusive in-game contents: - N7 Arsenal Pack – N7 Sniper Rifle, Shotgun, SMG, and Pistol - Robotic Dog – A sidekick on the Normandy - Squadmate Alternate Outfit Pack – New appearances for squad members - N7 Hoodie – Commander Shepard’s outfit on the Normandy. - Digital soundtrack - Xbox LIVE Normandy prop for Xbox 360 Avatar. - A collection of BioWare forum and social badges, avatars, and perks.' FROM games WHERE igdb_id = 45180 ON CONFLICT (game_id, language_code) DO NOTHING;
