INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Encounters: Deadwood', 'An outlaw called Blackjack killed 21 people before he died. Now grave robbers have opened his grave and unleashed a curse. The citizens of Deadwood are dying mysteriously, and you are tasked with lifting the curse and defeat Blackjack''s ghost. Solve hidden object scenes and mini games to collect hints and items in the ghost town of Deadwood.' FROM games WHERE igdb_id = 140254 ON CONFLICT (game_id, language_code) DO NOTHING;
