INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: Gravure for You! Vol. 7', 'This is the seventh volume of The Idolmaster Gravure For You! series. It has a new compilation of songs: "HIBIKI TurquoiseBlueMIX". While the rest of the original mixes contain the idols'' image color, Hibiki''s image color (light blue) is replaced with "Turquoise Blue". This volume also marked Ai Hidaka''s second HD appearance, featuring her in a special mode of the game. This mode allows players to take pictures of her while wearing the "Exercise Wear NEO" costume and allows them to listen to her sing the BGM music. Another unique option for this volume is the ability to add the accessory "Heartbreak Glasses" to the "Rough Time School" costume.' FROM games WHERE igdb_id = 79048 ON CONFLICT (game_id, language_code) DO NOTHING;
