INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Wanna Kill The Kamilia 2', 'I Wanna Kill The Kamilia 2 is an I Wanna Be The Guy fangame made by Influcca and it is the second entry of the medley game series "Kill The Kamilia". This is a sequel/remake to I Wanna Kill The Kamilia, a game originally made by oyo. Your mission is to, once again, defeat The Kamilia, but this time the challenges are much tougher and the stage remixes are much better refined.' FROM games WHERE igdb_id = 359703 ON CONFLICT (game_id, language_code) DO NOTHING;
