INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 3: The Lost Expeditions Edition', 'Far Cry 3: The Lost Expeditions Edition features two additional missions that allow you explore the WW2 forgotten ruins of the island. Find the way out to escape the research complex and the pirates standing between you and freedom. Also included is an extra multiplayer weapon, the Type 10 Japanese flare gun - a modified single-handed destructive shotgun.' FROM games WHERE igdb_id = 142159 ON CONFLICT (game_id, language_code) DO NOTHING;
