INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Walking Dead', 'The Walking Dead: Season One (also known as The Walking Dead: The Game) is an episodic interactive drama graphic adventure video game developed and published by Telltale Games. Based on Robert Kirkman''s The Walking Dead comic book series, the game consists of five episodes, released between April and November 2012. It is available for Android, iOS, Kindle Fire HDX, Microsoft Windows, Mac OS X, PlayStation 3, PlayStation Vita, Xbox 360, PlayStation 4 and Xbox One. The game is the first of The Walking Dead video game series published by Telltale.' FROM games WHERE igdb_id = 1871 ON CONFLICT (game_id, language_code) DO NOTHING;
