INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Collapsible D', 'Collapsible D is an engaging game about surviving in the dramatic last minutes of the Titanic shipwreck: lead a group of passengers to safety through the many decks of the ship as the icy waters of the Atlantic Ocean quickly flood the gigantic hull. Will you make it to the lifeboats in time?' FROM games WHERE igdb_id = 175516 ON CONFLICT (game_id, language_code) DO NOTHING;
