INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quiet, Please!', 'After an annoying day at school, you just want some peace and quiet. But everything at home is so noisy! Mr. Peabody is obsessively mowing his lawn, Dad is channel surfing and Mom is yapping on the phone. Your pesky kid brother won''t go to bed, and even your pet kittens are driving you crazy! Explore, interact with your environment and solve puzzles. 3 kittens included with every purchase!' FROM games WHERE igdb_id = 61294 ON CONFLICT (game_id, language_code) DO NOTHING;
