INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ore-sama-kingdom-ikemen-kareshi-wo-get-shiyo-moe-kyun-school-days', 141587, '2012-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4scw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch5l7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore-sama Kingdom: Ikemen Kareshi wo Get Shiyo! Moe Kyun School Days', 'This game, based off the anime and manga series "オレ様キングダム" or "Oresama Kingdom", stars Nono Nonohara, a young manga artist. Summer vacation has ended, and she has started high school! To her suprise, she finds out that her three friends, Shun Kurosawa, Shinogu Hakuba and Hikaru Akagi are all in the same class as her. After class they are talking when suddenly, the wind kicks up, and pages from her manga go flying everywhere! She and her friends all try to help her collect them from around their school. Suddenly, after finally collecting her drawings, she falls down the stairs. When she wakes up in the nurses office, she can''t remember anything! As Nono continues to go about her life drawing and doing schoolwork, she hangs out with her friends and will eventually regain her memories and maybe... love? The game is mostly made up of conversations between Nono and one of the boys, and then afterwards a test of her memory of the thing they just talked about, or a small mini game. If Nono is successful, she regains some of her memory, and gets a puzzle piece for that boy''s puzzle. A new puzzle piece is introduced each month, and the game plays out in a week by week system.' FROM games WHERE igdb_id = 141587 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 141587 AND ge.slug = 'visual-novel' ON CONFLICT DO NOTHING;
