INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rule the Kingdom', 'An epic RPG adventure awaits you in Rule the Kingdom! Outfit your character, train your loyal band of warriors and join the battle against trolls, skeletons and other baddies to save the empire from evil! Build homes for your workers, produce goods in your workshops, fortify your stronghold, and farm crops to feed your subjects in your quest to build a thriving kingdom!' FROM games WHERE igdb_id = 343760 ON CONFLICT (game_id, language_code) DO NOTHING;
