INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Universe', 'Cartoon Universe was a browser-based game developed by WB Games Montreal featuring Looney Tunes and Scooby-Doo characters. It was described as a free-to-play online world that will provide a safe, social environment for young kids to go on adventures, solve puzzles and play games with their favorite Looney Tunes and Scooby-Doo! characters The game was free-to-play with micro-transactions and a subscription option. It had an open beta in 2012 and was released for browsers in May 2013 with an iOS version available soon after. After the game was shutdown its mini-games were re-released in Cartoon Universe: Arcade and Wayforward reworked the story elements into Cartoon Universe: Adventure, though the animated cutscenes were replaced with character cutouts during text sections.' FROM games WHERE igdb_id = 247576 ON CONFLICT (game_id, language_code) DO NOTHING;
