INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Mensa Academy', 'American Mensa Academy is a brain training game that will give player''s minds the ultimate cerebral workout. Created in direct collaboration with Mensa, American Mensa Academy is packed with 100+ replayable levels of fun and stimulating mini-games and challenges for everyone, plus for those really looking to test their grey matter, there is a rigorous test designed to calculate your Mensa score, directly inspired by questions faced by those attempting to join the renowned global high IQ society.' FROM games WHERE igdb_id = 47630 ON CONFLICT (game_id, language_code) DO NOTHING;
