INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under Defeat HD', 'For over ten years, a war has raged on between the Empire and the Union with many lives lost. You will take control of one of the Imperial Forces most technologically advanced helicopters, the VKL5.03 (P) and use its destructive artilleries to bring down the enemy forces, and finally bring the war to an end.' FROM games WHERE igdb_id = 43951 ON CONFLICT (game_id, language_code) DO NOTHING;
