INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stay Dead', 'A new generation of video games is born: Stay Dead is the first Motion Picture game. Motion picture games are the union of movies and videogames. Finally, the sound and graphic quality of a movie joins effectively the interaction of a next generation videogame, creating a unique and involving game experience.' FROM games WHERE igdb_id = 10895 ON CONFLICT (game_id, language_code) DO NOTHING;
