INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dickme Dicki', 'Dickme Dicki is a Yume Nikki fangame. It stars a certain man, who has green hair and closed eyes. He appears to be a palette swap of Miserere''s protagonist. The game was intended to be a joke, with some blatant criticisms of developers'' shortcomings.' FROM games WHERE igdb_id = 202353 ON CONFLICT (game_id, language_code) DO NOTHING;
