INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spellforce-2-faith-in-destiny', 7041, '2012-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rjx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4svc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpellForce 2: Faith in Destiny', 'An all new campaign that fits into the SpellForce series and enriches the world of SpellForce, including favourite characters and quests. An all new race of demonic enemies are also playable in multiplayer mode, featuring new units and structures. Ride into battle on a fierce dragon and use new spells and effects to enhance your tactical possibilities. Innovative new Role-Playing-Strategy Genre. Click''n''Fight and Quick-Action-Buttons: The revolutionary control system guarantees instant action, and a wealth of unique tactical possibilities at your fingertips. Easy Skill tree system that allows individual character development. Enjoy a highly detailed and living fantasy world that adapts to the actions of the player: Fight monsters, gather items, adventure, trade and collect mighty artifacts to use for your battles. 5 different fractions: Lead The Realm, The Clans, The Pact, the Shaikan and the Nameless to victory, with 12 very different units consisting of infantry, cavalry and flyers. 10 different races: heroic humans, powerful elves, strong dwarves, barbaric trolls,battle-tested orcs, destructive barbarians, powerful dark elves, unbreakable gargoyles, malicious shadows and mean demonic powers.' FROM games WHERE igdb_id = 7041 ON CONFLICT (game_id, language_code) DO NOTHING;
