INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('detective-masochist-the-case-of-the-femdom-torture', 127660, '2012-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7i42.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detective Masochist -The Case of the Femdom Torture-', 'The story so far: Our pathetic, lazy hero and his childhood friend Satomi, as beautiful as she is brilliant. He lives his days in a hardboiled fantasy, playing at being a detective while barely managing to make ends meet. She''s attending a top university and looking after him by acting as his reluctant partner. Never quite managing to make it past "just friends", the two get wrapped up in a startling incident, and suddenly things are turned upside down! Due to the actions of a mysterious man, Satomi is transformed into a super sadist whose thirst for punishment cannot be quenched! The sadistic Satomi toys with our hero, twisting him this way and that...perhaps finally going so far as to force him to claim her virginity! "If I don''t change Satomi back to normal quickly...I''ll never be able to resist her punishment..." What fate awaits our hero? Will he be able to track down the mysterious man and save Satomi? And what will become of the two of them?!' FROM games WHERE igdb_id = 127660 ON CONFLICT (game_id, language_code) DO NOTHING;
