INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Secret Society', 'The Secret Society is a clandestine community of people with the unique ability to move through magic worlds. Your dear Uncle Richard, an elite member of this ancient order, has suddenly gone missing. After a period of despair, you realize that you too are blessed with these special powers and thus are the only one that can find him! Locate your beloved uncle, protect the sacred Artifact of the Order and thwart the forces threatening the entire society in this fantastic blend of hidden object tasks and puzzles!' FROM games WHERE igdb_id = 88642 ON CONFLICT (game_id, language_code) DO NOTHING;
