INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project X Zone: Limited Edition', 'Project X Zone is a crossover tactical role-playing game for the Nintendo 3DS developed by Monolith Soft with assistance from Capcom and Red Entertainment and published by Namco Bandai Games. The game is a follow up to the 2005 video game Namco × Capcom and features characters from Namco Bandai, Capcom, and Sega. The game was released on October 11, 2012 in Japan; June 25, 2013 in North America; and July 5, 2013 in Europe. The game received mixed to positive reviews on release; praise went towards the game''s cast, combat system, and presentation, but criticism was directed at its repetitive gameplay and confusing storyline.' FROM games WHERE igdb_id = 89877 ON CONFLICT (game_id, language_code) DO NOTHING;
