INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Sewer Run', 'Teenage Mutant Ninja Turtles: Sewer Run is a browser-based action game. The events take place directly after Teenage Mutant Ninja Turtles: Dark Horizons. The game consists of four levels that each have a racing section and a fighting section. The racing section has the Turtle selected race to catch up with the target before time runs out, while the fighting section has the Turtle defeat a selected number of Foot Soldiers by hitting back shuriken thrown at him.' FROM games WHERE igdb_id = 64715 ON CONFLICT (game_id, language_code) DO NOTHING;
