INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4: Golden - Solid Gold Premium Edition', 'An enhanced rerelease of Shin Megami Tensei: Persona 4 (2008) featuring quality-of-life improvements, gameplay enhancements, new locations, balance tweaks, online functionality, new difficulty options, an additional side character storyline and a changed endgame. Persona 4: Golden - Solid Gold Premium Edition box contents. P4G (The Game) One of the best RPGs of all time, now expanded and remastered to make full use of the power of Vita Hori Hard Pouch Sturdily built and stylishly customized, this case has a flap that stores games while it guards the screen Hori Face Cover Offers lightweight yet effective protection without blocking any major ports, so it never has to come off! Protective Skin Adorns your Vita with the stylish, vibrant aesthetics of Persona 4 and includes 8 matching wallpapers Stickers Starring characters from Persona 4, these stickers can be used to decorate anything you can think of!' FROM games WHERE igdb_id = 89923 ON CONFLICT (game_id, language_code) DO NOTHING;
