INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Second Wind', 'Second Wind is a roguelike RPG in which you''ll explore random dungeons as you battle monsters, upgrade your equipment and complete quests. You can choose and unlock new characters to play with, each character has 3 stats: dexterity, power and armor, which will increase or decrease during your adventure. Each character also has 3 unique battle moves, use them wisely!' FROM games WHERE igdb_id = 314531 ON CONFLICT (game_id, language_code) DO NOTHING;
