INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nemesis Macana', 'Standing in front of a London brothel with the clear intent to enter, our protagonist''s future may seem dark and foreboding. But perhaps an unexpected and life-changing experience is waiting for him. Comes with a manifesto about the relation between interactive fiction and sexuality, and its importance for our spiritual health.' FROM games WHERE igdb_id = 364630 ON CONFLICT (game_id, language_code) DO NOTHING;
