INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Pirate Warriors - Collector''s Edition', 'Pirate Warriors is an action game incorporating elements from both the Dynasty Warriors series and the One Piece series. The game''s story mode, Main Log, allows the player to play through the storyline. The Adventure mode uses Luffy to play through the events of the One Piece series and the battle mode allows the player to use characters in battles. In Another Log, the player can play through a character''s storyline. With it are several stories exclusive to the game. In addition to the game itself, the collector''s edition will exclusively offer the "Thousand Sunny", the ship on which Luffy''s crew sails the seas towards a horizon of adventures.' FROM games WHERE igdb_id = 225247 ON CONFLICT (game_id, language_code) DO NOTHING;
