INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elkrone-no-atelier-dear-for-otomate-limited-edition', 253495, '2012-04-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mm8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elkrone no Atelier: Dear for Otomate Limited Edition', 'Otomate-developed visual novel for the PlayStation Portable based on the turn-based RPG Atelier series by Gust. The limited edition of Elkrone no Atelier: Dear for Otomate comes with an audio drama CD and an exclusive artbook. Meriela (a.k.a Meri) has inherited her grandmother''s workshop, and now it''s up to her to decide what to do with it. One day, a fairy called Popotto pops up at the front door, asking her to create a mysterious item—the Blue Wakaka. Neither the client nor the alchemist have ever seen it, but since the fairy is in no great hurry, he decides to lodge with Meri to help her out with item synthesis, ingredient collection, monster fights and finding her soul mate.' FROM games WHERE igdb_id = 253495 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 253495 AND ge.slug = 'visual-novel' ON CONFLICT DO NOTHING;
