INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('4-elements-ii-special-edition', 106038, '2012-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3sjm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scd2oc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4 Elements II: Special Edition', 'Discover the fantastic world of 4 Elements in this Windows exclusive Special Edition of the acclaimed Puzzle and Hidden Object game. Four fairies representing the elements of earth, air, fire, and water have been deprived of their magic power. Be the hero of the kingdom and restore their magic! Lose yourself in beautiful backgrounds, music and amazing graphics. Explore a world of color, animation, and mystical delight. Discover secrets, solve intriguing puzzles, and decipher the book of magic to unlock powerful spells. 4 Elements™ II: Special Edition is an exciting “match three” game packed with fascinating puzzles and hidden object challenges. This Special Edition includes 48 exclusive levels for Windows, 14 of which you can play for free in the trial version! This edition also includes six custom Windows wallpapers and the complete original soundtrack in MP3 format. Compare your progress with friends via leaderboards, and earn 200 Xbox Gamerscore points, and 20 challenging Achievements.' FROM games WHERE igdb_id = 106038 ON CONFLICT (game_id, language_code) DO NOTHING;
