INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amatsu Misora ni! Kumo no Hatate ni', 'Amatsu Misora ni!: Kumo no Hatate ni is a romantic fantasy comedy for PlayStation handhelds which originated as an adult visual novel for PC (Windows) under Amatsu Misora ni! title. PSP and PS Vita ports don''t really have new content to offer, but they do have all the adult content that is available in PC version, removed. Each of the game''s graphics has been tuned and adjusted to match that of PC and look better on a device the game is played on.' FROM games WHERE igdb_id = 62263 ON CONFLICT (game_id, language_code) DO NOTHING;
