INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chivalry: Medieval Warfare', 'Chivalry: Medieval Warfare is a fast-paced online multiplayer action game which will have players turning in their guns and grenades for battle axes and swords. Chivalry: Medieval Warfare combines a sharp melee edge and familiar competitive gameplay along with the genuine look and feel of open-field combat in the Middle Ages. Players will use different attacks, blocks and counters insuring that combat is tactical, responsive and of course chaotic.' FROM games WHERE igdb_id = 2358 ON CONFLICT (game_id, language_code) DO NOTHING;
