INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-gear-solid-social-ops', 41040, '2012-12-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3dmq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid: Social Ops', 'Metal Gear Solid: Social Ops (officially abbreviated MGS SOP) was a 3D mobile game. It was released exclusively in Japan for the iPhone and Android smartphones on December 6, 2012. The game involved gameplay and re-enactment from the games Metal Gear Solid 3: Snake Eater and Metal Gear Solid: Peace Walker. Social Ops was similar to the Metal Gear Acid series in terms of character movement and its use of items and weapons via trading cards. The trading cards involved characters and enemies from Metal Gear, Metal Gear 2: Solid Snake. Metal Gear Solid, Metal Gear Solid 2: Sons of Liberty, Metal Gear Solid 3: Snake Eater, Metal Gear Solid 4: Guns of the Patriots, Metal Gear Solid: Peace Walker, Metal Gear Rising: Revengeance and Metal Gear Solid V: Ground Zeroes. Besides cards relating to the Metal Gear series, there were also cards related to Zone of the Enders, another series of games by Kojima Productions and collaboration cards with other GREE game series such as Cerberus Jihad and Dragon Collection. The game''s official website was launched on August 30, 2012. On October 2013, Konami announced via the Social Ops website that the servers of the game would come to an end. The final mission was downloadable on October 31, 2013 til November 13, 2013. The game was then removed from being downloaded on December 13, 2013 and the service ended for good on January 31, 2014. All players unused credits from the "Metal Gear Solid Coin" bank was refunded.' FROM games WHERE igdb_id = 41040 ON CONFLICT (game_id, language_code) DO NOTHING;
