INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Ghost Recon: Future Soldier', 'The story of a Vengeance, the history of a secret war. When a stolen military grade bomb takes out a Ghost squad, a new Ghost Unit must track down the source of the weapons. But the trail Kozak, Ghost Lead, Pepper and 30K follow leads around the world, into the corridors of power where rebellion and war are brewing. Soon, the Ghosts are all that stands between the world and a devastating global conflict.' FROM games WHERE igdb_id = 1293 ON CONFLICT (game_id, language_code) DO NOTHING;
