INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oumagatoki: Kaidan Romance', 'Oumagatoki: Kaidan Romance was released in 2012. It is the first game in the Kaidan Romance series. The Kaidan Romance games are split into three sets of games set in the same world but with different characters and protagonists. This is the first game in the Suzue Shizuka line, with the sequel being Tasogaredoki ~Kaidan Romance~.' FROM games WHERE igdb_id = 219135 ON CONFLICT (game_id, language_code) DO NOTHING;
