INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat: Komplete Edition', 'This Komplete Edition is a re-release of the original game. It includes the full game, alongside all previously released downloadable content. It also includes the Mortal Kombat: Songs Inspired by the Warriors album (including a bonus track) and the 1995 Mortal Kombat movie for download, via the PlayStation Store or Xbox Live Zune. For the PS Vita and Windows this is the first release of the game. It has the same content as well as new costumes and a new Challenge Tower (Vita version only) not featured in the versions for other platforms.' FROM games WHERE igdb_id = 2977 ON CONFLICT (game_id, language_code) DO NOTHING;
