INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('damage-inc-pacific-squadron-wwii', 16392, '2012-07-02', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60gs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kvlxe9qho1tu8bhog10t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Damage Inc. Pacific Squadron WWII', 'Take to the skies in one of over 30 accurately represented aircraft and defend the Pacific Theatre from invading enemy forces. Fight your way through intense air-to-air, air-to-ship, and air-to-ground combat while piloting dive bombers, fighters, and torpedo bombers over visually striking, historically accurate locations. From the surprise attack on Pearl Harbor to the fierce Battle of Iwo Jima, outmaneuver your foes through more than 20 multi-objective single-player and co-op missions, or engage in head-to-head dogfights against online rivals. Whether flying alone, alongside, or against your teammates, use your aerial arsenal to devastate the enemy and dominate the air.' FROM games WHERE igdb_id = 16392 ON CONFLICT (game_id, language_code) DO NOTHING;
