INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of Pen and Paper +1 Edition', 'Set out on a grand adventure in this turn-based, retro style, pixel-art RPG, inspired by the great titles of the 90''s. Take on the roles of in-game players taking on the roles of their characters in a traditional pen and paper RPG session in the ultimate meta roleplaying experience.' FROM games WHERE igdb_id = 2934 ON CONFLICT (game_id, language_code) DO NOTHING;
