INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Absolute Supercars', 'From the racing minds at Eutechnyx comes the definitive auto package for every hardcore driving fan''s wildest dreams: Absolute Supercars! This racing game allows people of all ages and skill to get behind the wheels of some of the world''s most powerful supercars. Take part in quick races, time trials, championships and even an epic Career mode in an attempt to earn the big bucks and fill your Showroom with a cavalcade of stunning motors! From Ferrari, to Pagani, to Aston Martin and McLaren, there''s a car for everyone and a series of stunning tracks to race them on.' FROM games WHERE igdb_id = 42997 ON CONFLICT (game_id, language_code) DO NOTHING;
