INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am Alive', 'I Am Alive casts the player as a lone survivor in a believable, dark and insecure post-apocalyptic world. One year after the Event, a worldwide cataclysmic event that wiped most of the human race, a man struggles for survival in a desolate city as he tries to reunite with his long-lost wife and daughter.' FROM games WHERE igdb_id = 507 ON CONFLICT (game_id, language_code) DO NOTHING;
