INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Achievement Unlocked 3', 'Does reading this text earn you an achievement? Well, no, but 400 achievements await you in this latest installment in the AU franchise. Once again play as the Blue Elephant as he makes his way through complex puzzle maps in his quest to earn all achievements and escape to freedom. But beware; King Hamster (who is actually a guinea pig... but don''t tell him that) won''t make it easy on you. And while spikes, flaming rodents, and perilous pits await you, ultimately your foe is time itself. So good luck on your most elephantastic adventure!' FROM games WHERE igdb_id = 179276 ON CONFLICT (game_id, language_code) DO NOTHING;
