INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokimeki Memorial Girl''s Side Premium 3rd Story', 'Tokimeki Memorial Girl''s Side Premium 3rd Story is an enhanced port of Tokimeki Memorial Girl''s Side: 3rd Story on the Nintendo DS. New features: • New character Tatsuya • Renewed graphics with a 2D animation system • "Boys'' Life" mode, where the player can watch super-deformed versions of the main male characters interact with their bedrooms.' FROM games WHERE igdb_id = 144531 ON CONFLICT (game_id, language_code) DO NOTHING;
