INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Journey Down: Chapter One', 'In a shady corner of Kingsport Bay at the outskirts of St Armando, Bwana and his trusted sidekick Kito struggle to make ends meet at their run-down gas station. Little do they know that they are about to be thrown into a spine-tingling adventure that will take them far from home and right into a twisting plot of corruption and danger. In the first chapter of The Journey Down, the search for a lost journal leads to forgotten secrets of the mysterious Underland. Follow Bwana and Kito as they puzzle their way forward and begin to uncover the true fate of their long lost father, Captain Kaonandodo.' FROM games WHERE igdb_id = 9048 ON CONFLICT (game_id, language_code) DO NOTHING;
