INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'aerofly FS', 'Fulfill your dream of flying with aerofly FS! aerofly FS lets you enter the world of flying in a quality never seen before. aerofly FS sets a high value on realistic flight physics, highly detailed aircraft and terrain and smooth frame rates. At the same time, aerofly FS features an intuitive user interface and requires virtually no training time. Fly either with your joystick, gamepad, mouse or keyboard.' FROM games WHERE igdb_id = 16383 ON CONFLICT (game_id, language_code) DO NOTHING;
