INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harry-potter-for-kinect', 20743, '2012-11-09', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20e9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceggd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter for Kinect', 'For the first time, create a witch or wizard character in your likeness that will become part of the gameplay through Kinect''s scanning technology. Experience unforgettable moments from all eight films - from having your wand choose you at Ollivanders and being Sorted as a first-year student at Hogwarts, to battling You-Know-Who in a climactic wizard battle Cast spells at your opponents by performing the proper casting maneuvers and calling out spell names utilizing Kinect''s controller-free and voice recognition capabilities. Hone your casting, brewing and duelling skills (among others) in class to unlock even more lessons and challenges Challenge a friend in competitive mini-games, or join forces against a mutual opponent in co-op games.' FROM games WHERE igdb_id = 20743 ON CONFLICT (game_id, language_code) DO NOTHING;
