INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spec Ops: The Line', 'A third-person shooter in which three American soldiers led by Capt. Walker are sent to Dubai in order to recover whoever remains of an infantry unit, the 33rd Battalion, until they decide to take action against the militants situated in the city. As they progress, however, the logistical and ethical complexity of their objective deepens, and their perception of themselves, and their enemy, is put into question.' FROM games WHERE igdb_id = 1377 ON CONFLICT (game_id, language_code) DO NOTHING;
