INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-chronicles-of-shakespeare-a-midsummer-nights-dream', 9401, '2012-07-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/en6ixqj4s9qxudaskwur.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chronicles of Shakespeare: A Midsummer Night''s Dream', 'Experience one of the Bard''s most beloved tales in The Chronicles of Shakespeare - A Midsummer Night''s Dream, a wonderful point-and-click journey. One of Shakespeare''s magnificent plays, here''s your chance to experience it as never before. Live the lighthearted antics of the events surrounding the marriage between Theseus, Duke of Athens, and Hippolyta, Queen of the Amazons. These include the adventures of four the young Athenians and the six amateur actors of the play within the play. Journey along with the young Shakespeare and see the antics play out in this fun adventure. Explore all of the fantastic locations made famous by his work. Solve a host of dazzling puzzles and mini-games. Come face-to-face with all of the astonishing characters created for this beloved play.' FROM games WHERE igdb_id = 9401 ON CONFLICT (game_id, language_code) DO NOTHING;
