INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PlanetSide 2', 'PlanetSide 2 is a Massively Multiplayer first person shooter that delivers truly epic, massive combat on a scale never before seen in stunning, breathtaking detail. Battles take place not between dozens of troops, but thousands; with air and ground vehicles slugging it out alongside squads of troops. Whether in open fields, tightly-packed urban centers or enormous structures, winning requires strategic teamwork and a quick trigger finger.' FROM games WHERE igdb_id = 1265 ON CONFLICT (game_id, language_code) DO NOTHING;
