INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms Revolution: Gold Edition', 'Includes: Worms Revolution, Worms Revolution - Customization Pack, Worms Revolution - Mars Pack, Worms Revolution: Funfair DLC, Worms Revolution: Medieval Tales DLC Worms Revolution is another entry in the classic turn-based strategy series to come to the PC, featuring exciting new features and beautiful 3D graphics whilst retaining the classic 2D gameplay that fans love. Choose to play the extensive single player mode which features both campaign and puzzle missions or dive straight into multiplayer warfare via local play. For the first time ever see the inclusion of dynamic water, physics objects and worm classes! Customise your experience by choosing what classes you play with, what they look like and even how they speak! Worms Revolution sticks an exploding sheep under worm-on-worm conflict and blasts it squarely into the 21st century.' FROM games WHERE igdb_id = 52111 ON CONFLICT (game_id, language_code) DO NOTHING;
