INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seduced in the Sleepless City', 'Editor of a woman’s magazine, you’re assigned to cover the grand opening of a new hotel and casino. In the party’s VIP room, you get up close and personal with a famous actor, a best-selling novelist, a charismatic plastic surgeon, and an F1 racer.' FROM games WHERE igdb_id = 220877 ON CONFLICT (game_id, language_code) DO NOTHING;
