INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Kiss For the Petals: Maidens of Michael', 'Amidst the flirtations of couples, established and spontaneous ones alike, excitement was brewing over the informal student poll to decide "St. Michael''s Best Couples." Not having a girlfriend, Risa didn''t think the matter concerned her... Until she and Miya were chosen as a pair!' FROM games WHERE igdb_id = 83995 ON CONFLICT (game_id, language_code) DO NOTHING;
