INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('forza-motorsport-4-essentials-edition', 47395, '2012-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/u2zufgrvjm0rpppwppan.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Motorsport 4: Essentials Edition', 'Forza Motorsport 4 is a racing video game developed by Turn 10 Studios and published by Microsoft Studios for the Xbox 360. It is the fourth installment in the Forza Motorsport series. It is the first title in the series to support the Kinect sensor alongside the traditional controller-based gameplay. New to the series is the Autovista mode, a mode in which players can view precise details such as engine parts and interior gauges on a select number of cars. It features a partnership with BBC''s Top Gear as well as its American counterpart. Jeremy Clarkson, presenter for Top Gear, provides commentary in the game''s Autovista mode. Other partnerships include a two-year agreement with the American Le Mans Series (ALMS). Over 500 cars and 26 tracks are included. The game received universal acclaim from critics. Aggregate websites GameRankings and Metacritic report scores of 90.50% and 91 out of 100, respectively. Metacritic also reports eight perfect scores from various media outlets. Critics praised the enhanced vehicle physics, updated visuals, and strong sound design. Several reviewers also gave high marks for the Forza 4 ''​s Autovista mode. Some critics expressed frustration with Kinect features, and others also felt that the game was not enough of an innovation from its predecessor, Forza Motorsport 3. These critics did, however, concede that the game was a vast improvement over Forza 3.' FROM games WHERE igdb_id = 47395 ON CONFLICT (game_id, language_code) DO NOTHING;
