INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gardenscapes-mansion-makeover', 294685, '2012-05-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8095.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvn9i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gardenscapes: Mansion Makeover', 'Use your talents to straighten up the indoors with Gardenscapes: Mansion Makeover, a splendid sequel to the hit game. Having restored the garden to its original splendor, the time has come to have some guests over and show it off. The mansion has a spacious hall for everyone to gather but unfortunately, you''ve spent all of your time on the outside and the hall is in need of a similar makeover. The wallpaper is curling, the fireplace is broken, and heaps of old newspapers lie scattered about. It''s time to roll up your sleeves yet again and turn the hall back into an inviting masterpiece. Join Austin the butler as you scour the old mansion for new items to sell in this quirky blend of Hidden Object and Time Management gameplay. Invite neighbors to your rummage sale and comb the mansion rooms for items on their wanted list. The faster you serve them, the more money you are certain to make in order to repair the house and customize it to your liking.' FROM games WHERE igdb_id = 294685 ON CONFLICT (game_id, language_code) DO NOTHING;
