INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asura-s-wrath', 5495, '2012-02-21', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4961.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zb5xknyz7nn3vy7pu5pb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asura''s Wrath', 'The game follows the title character, the demigod Asura as he seeks revenge on the pantheon of other demigods who betrayed him. The story is presented in the style and format of an episodic series of cinematic shorts, including opening and closing credits, with the gameplay being integrated into the cinematic where players switch between third-person combat and interactive sequences with player input in the form of quick-time event button prompts. Because of its unique style, the game has been described in the media as an "interactive anime". According to the game''s producer Kazuhiro Tsuchiya, Asura''s Wrath takes elements from Hinduism and Buddhism and blends them with science fiction, with the main character based on the ever combative and superiority-seeking beings of the same name that are part of the Hindu and Buddhist cosmology.' FROM games WHERE igdb_id = 5495 ON CONFLICT (game_id, language_code) DO NOTHING;
