INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slush Invaders: Game', 'A stickman skill-toss flash game made by Gildedguy where you must rescue your captured fighters and stop the villain by launching him into the skies. It has a very colorful aesthetic, derivative from stick animations from it''s time. Features a lot of playable characters that allows for different team combinations with varying functions and upgrades for each member.' FROM games WHERE igdb_id = 278199 ON CONFLICT (game_id, language_code) DO NOTHING;
