INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Good Life', 'The Good Life, a Tropical Paradise Simulation, is a game that captures the spirit of a laid-back lifestyle in a visually stunning 3D tropical environment. Travel around with an impressive array of luxury vessels, while managing tourist campaigns and real estate business and completing missions on your way to becoming the area''s top tycoon.' FROM games WHERE igdb_id = 9396 ON CONFLICT (game_id, language_code) DO NOTHING;
