INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Crossing: New Leaf', 'The charming community-building franchise returns for with Animal Crossing: New Leaf. The Nintendo 3DS entry into this popular franchise introduces a number of options new to Animal Crossing, including the ability to become the head of the village and boost its development, a way to install certain items in the village to make its characteristics more personalized for each player, and the ability to view homes of other players who are tagged through StreetPass connections.' FROM games WHERE igdb_id = 2687 ON CONFLICT (game_id, language_code) DO NOTHING;
