INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy!', 'This 2012 update of the classic Jeopardy! quiz game includes 3,000 clues in the Jeopardy!, Double Jeopardy! and Final Jeopardy! formats. The game also includes the premier of the "Jeopardy! Clue Crew" for the first time in a home game format, while also featuring host Alex Trebek and announcer Johnny Gilbert. Between rounds multiplayer mini-games are offered as breaks. Online multiplayer is supported to play against other players.' FROM games WHERE igdb_id = 28472 ON CONFLICT (game_id, language_code) DO NOTHING;
