INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hatsune-miku-and-future-stars-project-mirai', 6805, '2012-03-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ty8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gflmv6xblnr93fscdmyg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku and Future Stars: Project Mirai', 'Hatsune Miku and Future Stars: Project Mirai is a rhythm game and a spin-off of the Hatsune Miku: Project DIVA series of Vocaloid rhythm games. Like the original the game primarily makes use of Vocaloids, a series of singing synthesizer software, and the songs created using these vocaloids most notably the virtual-diva Vocaloid Hatsune Miku. The game features different character designs than the main games and the characters appear as their Nendoroid-style, Super deformed versions. For the game''s primary gameplay, its music mode, it uses what it calls the "Chance Circle System". Buttons will appear around the border of a circle, and a pointer will appear from the center of the circle extending all the way outside the circle''s border. It will then turn in a clockwise or counter-clockwise manner according to the song and when the pointer passes the button, the player has to press the face button on the 3DS. Similar to the series, the player''s time accuracy will also be rated on a similar scale and manner that will be displayed on the bottom of the screen. In addition the game does not feature the Edit Mode of the Project DIVA series, while the DIVA Room Mode is replaced by the game''s My Room mode whereby players similarly get to interact with their modules in a room.' FROM games WHERE igdb_id = 6805 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 6805 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
