INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Republia Times', 'The Republia Times is a free-to-play indie browser video game created by Lucas Pope, released in April 2012. In the game, the player takes the role of the editor of a newspaper torn between personal opposition to the government and threats to the lives of the editor''s wife and children if the editor does not generate loyalty among the population. Originally created as a warm up for a Ludum Dare game jam, The Republia Times was nominated in two categories in the Games for Change Awards.' FROM games WHERE igdb_id = 134491 ON CONFLICT (game_id, language_code) DO NOTHING;
