INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Tamer', 'Chaos spreads over the earth. Savage monsters run wild. A once peaceful village collapses under the turmoil. All hope is lost… But wait…a brave young monster tamer survives. Those he cannot tame, he must destroy.' FROM games WHERE igdb_id = 366100 ON CONFLICT (game_id, language_code) DO NOTHING;
