INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medal of Honor : Warfighter - Limited Edition', 'The most authentic shooter this year, Medal of Honor Warfighter is the only game that puts players in the boots of the world’s most aggressive, precise and disciplined warfighters, fighting battles that are ripped from headlines around the globe. Powered by the ground-breaking Frostbite 2 engine, Medal of Honor Warfighter delivers tomorrow’s technology on today’s platforms with advanced gameplay, visuals and sound design.' FROM games WHERE igdb_id = 47411 ON CONFLICT (game_id, language_code) DO NOTHING;
