INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4 Arena', 'Persona 4 Arena is a fighting video game developed for Japanese arcades and later ported to home consoles. Based on Atlus'' Persona role-playing game series, Arena serves as a direct sequel to Persona 4 and features characters from its predecessor, Persona 3. Atlus wrote the story to the game while Arc System Works handled the gameplay.' FROM games WHERE igdb_id = 5650 ON CONFLICT (game_id, language_code) DO NOTHING;
