INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drakerider', 'Kill or be killed. Experience the perils of adventure with your ferocious sidekick in this brand-new smartphone RPG! Led by Akifumi Kaneko, the game is developed by WITCHCRAFT Inc., famous for their work on various anime and other RPGs. This title maintains the high quality and integrity for which they are known.' FROM games WHERE igdb_id = 342797 ON CONFLICT (game_id, language_code) DO NOTHING;
