INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doodle Cat', 'Meet the Doodle Cat! Create the Doodle Cat''s Universe filled with objects and let him play with them! Like all cats, Doodle Cat loves to play, eat and sleep. But most of all Doodle Cat loves to discover and explore, and have new adventures! Combine and match various items to create new experiences for Doodle Cat. Any item you create is sure to get his curious nose twitching, and he will be happy to play with it!' FROM games WHERE igdb_id = 343797 ON CONFLICT (game_id, language_code) DO NOTHING;
