INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Open Me!', 'An addictive augmented reality puzzle game for the PS Vita system that challenges players to think “outside the box”. The goal is simple: open the box and collect the items inside. But be prepared – each box has its own unique traps that require you to think creatively.' FROM games WHERE igdb_id = 64291 ON CONFLICT (game_id, language_code) DO NOTHING;
