INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted: Fight for Fortune', 'Uncharted: Fight for Fortune is a strategic turn-based card game based on the Uncharted series. The game pits two players against each other, represented by characters from the series. The players use their decks of cards to defeat the opposing side. The game can connect with Uncharted: Golden Abyss, earning the player new cards based on their progression in the campaign and the trophies they have earned. Cards in the main game come from Uncharted: Drake''s Fortune, Uncharted: Golden Abyss, and the video series Uncharted: Eye of Indra. Two expansion packs were made available on the PlayStation Network to add cards from Uncharted 2: Among Thieves and Uncharted 3: Drake''s Deception.' FROM games WHERE igdb_id = 19583 ON CONFLICT (game_id, language_code) DO NOTHING;
