INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Manager 2013', 'Football Manager 2013 (often abbreviated to Football Manager 13, or more commonly FM13) is a 2012 football management simulation video game developed by Sports Interactive and published by Sega. It was released on Microsoft Windows and OS X on 2 November 2012. Football Manager Handheld 2013 was subsequently published for PlayStation Portable on 30 November, and for iOS and Android on 13 December.' FROM games WHERE igdb_id = 8974 ON CONFLICT (game_id, language_code) DO NOTHING;
