INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('master-of-alchemy', 10540, '2012-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ak97nbe4srteyj9bc9dv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ucq5kgohwe4kvxhcgq8f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Master of Alchemy', 'Master of Alchemy is an original and engaging puzzle game based on the manipulation and combination of solid, liquid and gaseous elements. A real physics engine grants the elements a credible behavior, as they stream through the Alchemist’s mysterious instruments and machines. Thanks to these tools, you will blend, fuse, sublimate, condense or break up elements. You''ll discover more and more instruments as you delve deeper into the game -and there are lots of puzzles to be solved. Will you be able to attain the utter domination over matter itself? Master of Alchemy – Rise of the Mechanologists will make you part of the war between two powerful factions –the alchemists and the mechanologists, who are tech-oriented, ruthless scientists. At the beginning of the story, you’ll choose your character among a group of six, following their evolution as the game unfolds. Master of Alchemy - Rise of the Mechanologists is the PC/ Mac version of the acclaimed iPad/iPhone game, developed by Darkwave Games and published by Forge Reply. Enjoy this fully reworked, rebranded experience and test your wits against the ancient art of alchemy!' FROM games WHERE igdb_id = 10540 ON CONFLICT (game_id, language_code) DO NOTHING;
