INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trials Evolution', 'Trials Evolution is a downloadable 2.5D platform racing game developed by RedLynx and published by Microsoft Studios. Successor to 2009''s critically acclaimed Trials HD. The game uses 3D graphics, but is played on a 2D plane, so the rider can only move forwards and backwards. Players can also control the bike''s pitch at slow speeds or while in the air. Players can also design and share their own maps utilizing the in-game editor. As with its predecessor, Trials HD.' FROM games WHERE igdb_id = 2149 ON CONFLICT (game_id, language_code) DO NOTHING;
