INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakadashi Banzai 5', 'Summer! The Beach!! Flirting, F*cking, and Finishing Inside!!! He''s the guy who loves nothing more than hitting on a chick, having raw sex, and ending with a creampie...Our hero is back once again!! This time, the hunting grounds are the shining sands of a midsummer beach!! Beautiful women in stunning swimsuit as far as the eye can see. Your targets are a blonde foreigner with a slamming body, a sexy, tanned, and flat chick, and a glamorous, mature wife in her 40s! Get their guard down with some flirting, enjoy sex under the summer sun or bathed in pale moonlight, and finish it off with a creampie! The world of Nakadashi Banzai is waiting for you!' FROM games WHERE igdb_id = 249102 ON CONFLICT (game_id, language_code) DO NOTHING;
