INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'For Rent: Haunted House', 'How will you screw over your tenants? Will you ignore inconvenient supernatural phenomena, or use them to drum up publicity? How will you deal with ghost hunters, squatters, and celebrity tenants? Will you emerge as the top agent? Or will you become a permanent resident of 57 Crowther Terrace?' FROM games WHERE igdb_id = 83600 ON CONFLICT (game_id, language_code) DO NOTHING;
