INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fist of the North Star: Ken''s Rage 2', 'Kenshiro and over twenty other characters from the Fist of the North Star series are ready to unleash rage in another game from Tecmo Koei. Fist of the North Star: Ken''s Rage 2 has Legend mode that covers the entire manga storyline from the Raoh Saga to the Land of Shura. Dream Mode has original storylines made just for the game that often focus on minor characters from the Fist of the North Star series.' FROM games WHERE igdb_id = 5313 ON CONFLICT (game_id, language_code) DO NOTHING;
