INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms Revolution', 'Worms Revolution is the latest game in the classic turn-based strategy series to come to the PC, featuring exciting new features and beautiful 3D graphics whilst retaining the classic 2D gameplay that fans love. Choose to play the extensive single player mode which features both campaign and puzzle missions or dive straight into multiplayer warfare via online or local play. For the first time ever see the inclusion of dynamic water, physics objects and worm classes! Customize your experience by choosing what classes you play with, what they look like and even how they speak!' FROM games WHERE igdb_id = 9334 ON CONFLICT (game_id, language_code) DO NOTHING;
