INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Team Umizoomi & Dora''s Fantastic Flight', 'What happens when Dora the Explorer and Team Umizoomi unite for the very first time? You get a high-flying adventure! Help the mighty math heroes Milli, Geo and Bot and super explorers Dora and Boots find the missing pieces of an extraordinary air-ship, and take to the skies with their Nickelodeon friends. It''s a one-of-a-kind journey!' FROM games WHERE igdb_id = 7980 ON CONFLICT (game_id, language_code) DO NOTHING;
