INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glass Heart Princess', 'The protagonist is beautiful, smart, and good at sports. She is the perfect daughter of a respected family. However, she is suddenly stricken with a bizarre disease called "Glass Heart Syndrome". If her heart rate rises above normal, she will die. The only cure is to train her heart by experiencing heart-pounding situations through dating!' FROM games WHERE igdb_id = 64163 ON CONFLICT (game_id, language_code) DO NOTHING;
