INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frederic: Resurrection of Music', 'Frederic Chopin – a long time deceased classical compositor – returns back from beyond the grave to fight intense musical duels. In his way stand some of the worlds greatest pop stars charmed with enormous profits that wild commercialization provides' FROM games WHERE igdb_id = 9846 ON CONFLICT (game_id, language_code) DO NOTHING;
