INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape Plan', 'Escape Plan™ takes advantage of the PlayStation®Vita system''s multi-touch display, rear touch panel, swipe interfaces and motion sensor, putting the fate of the hapless heroes in the palm of your hand. Players can swipe, squeeze, poke and slap Lil and Laarg to manipulate the characters and interact with the diverse environments. Only you can help them survive each deadly room before their captor and nemesis, Bakuki, recycles them and turns them into his minions... or sheep.' FROM games WHERE igdb_id = 18371 ON CONFLICT (game_id, language_code) DO NOTHING;
