INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack the Ripper - Letters from Hell', 'It is London during the summer of 1888. On the hunt for spicy stories, the reporter Bert goes on the trail of Jack the Ripper, the famous serial killer that is terrorising the White Chapel district. He goes as far as falsifying letters from Jack the Ripper and sends them to the police. But his involvement in this affair soon makes him the ideal suspect for the police at Scotland Yard.  Help Bert prove his innocence and conduct his own investigation in order to clear up the mystery of the White Chapel killer!' FROM games WHERE igdb_id = 122098 ON CONFLICT (game_id, language_code) DO NOTHING;
