INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nomolos-storming-the-catsle', 48699, '2012-03-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rbg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc90fh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nomolos: Storming the Catsle', 'Nomolos is a platformer for the Nintendo Entertainment System. It is the first release of the retro studio Gradual Games  -Guide Nomolos through 12 action packed levels and defeat 4 of Boulder''s most fearsome henchmen before finally confronting the evil Hippo in her lair, the Catsle. You will have to contend with dozens of Boulder''s denizens, but fortunately powerful weapons and helpful powerups are laying around the realm that Nomolos can use to help him on his way.   -Easy mode for novices, and two additional difficulty levels for those who like a little extra challenge.   -Enjoy an all-baroque soundtrack with music by Domenico Scarlatti, Johann Sebastian Bach, Jean-Phillipe Rameau, Francois Couperin, and Antonio Francisco Javier Jose Soler Ramos.' FROM games WHERE igdb_id = 48699 ON CONFLICT (game_id, language_code) DO NOTHING;
