INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murasame', 'Murasame is a tense and atmospheric survival-suspense adventure game that blends action, exploration, and narrative choices to create a gripping one-night escape drama. The game begins with a typical school trip that turns into a nightmare when a sudden landslide traps a group of students. Stranded and seeking help, they find a nearby village—but what they discover there is far more dangerous than anyone expected.' FROM games WHERE igdb_id = 383814 ON CONFLICT (game_id, language_code) DO NOTHING;
