INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conception: Ore no Kodomo wo Undekure!', 'Conception: Ore no Kodomo o Undekure! is a Japanese role-playing game and the first game in Spike Chunsoft''s Conception series. The player''s goal is to charm pure, innocent girls from Granvania National Star God Academy, raise their affection for Itsuki, then produce and take the "Star Children" to explore dungeons and battle "impurities".' FROM games WHERE igdb_id = 4702 ON CONFLICT (game_id, language_code) DO NOTHING;
