INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Music Girl Hatsune Miku', 'Music Girl Hatsune Miku was a communication-type game that revolved around the player interacting with Hatsune Miku. The player could access their MP3 files from their phones and play a song for Miku to listen to, and even move to the song''s rhythm if a BPM is matched. Players could even engage with Miku in activities such as answering trivia questions and playing "patty-cake" type games. These activities would increase the friendship gauge on the top-left corner of the screen and should it fill up at specific points, Miku would reward the player with a gift.' FROM games WHERE igdb_id = 368411 ON CONFLICT (game_id, language_code) DO NOTHING;
