INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ether-vapor-remaster', 10280, '2012-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2usb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrnb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ether Vapor Remaster', 'All hope seems to be lost for the country of Lydia in their war against Caldea, which has a huge advantage in numbers and technology. Into the midst of this war flies an unknown pilot in a prototype fighter... His agenda and the secret to the his awesome firepower will be revealed as he takes on overwhelming numbers of enemy fighters and massive bosses to reach his final objective.  Ether Vapor Remaster is a cinematic 3D arcade shooter and visual treat from developer Edelweiss. Explosions, lasers, ships and backgrounds are breathtakingly rendered. The dynamic camera uses vertical, horizontal and cinematic chase cam views to switch up the action and highlight the drama. Use multi-lock-on to shoot tens of missiles at a time and even blow up an entire battleship in the challenging Bonus Zones.' FROM games WHERE igdb_id = 10280 ON CONFLICT (game_id, language_code) DO NOTHING;
