INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wurm-online', 22677, '2012-12-12', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vuh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfmm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wurm Online', 'Wurm Online is a totally unique, highly accessible online wilderness MMORPG that will drag you in, shake you up and down, bite you, annoy you, drive you completely mad and leave you wondering why you didn’t find it a million years ago! Both PvP and PvE server clusters are available. On the Freedom PvE cluster, you can enjoy a peaceful life being eaten by bears in the woods. One of those servers offers opportunities to get a taste for fighting with other players, though. The Epic PvP cluster offers a lot of opportunities to fight and compete with other players. It also has bears, so watch out! You can transfer your account between the clusters at any time, skills and items do not transfer but are kept intact. Playing is easy. Just register for free and then download the Java client and packages by clicking on the Play! button on the site. Oh, you need Java, but there is a handy link for Java up to the right. Java is, of course, platform-independent, which means you can play Wurm on Linux, Mac, and even Windows!' FROM games WHERE igdb_id = 22677 ON CONFLICT (game_id, language_code) DO NOTHING;
