INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Moon', 'Embark on an epic adventure that leads you through a beautiful, isometric, open world with detailed high-definition visuals. Rainbow Moon is a strategy RPG with a strong emphasis on exploration, character development and turn-based battles. Six playable main characters with upgradeable weapons, armor and accessories; about 100 special skills and more than 20 challenging dungeons are awaiting you in a fascinating story that lasts over 40 hours. Rainbow Moon is a game by gamers, dedicated to gamers.' FROM games WHERE igdb_id = 5026 ON CONFLICT (game_id, language_code) DO NOTHING;
