INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fieldrunners 2', 'Strategic-Action-Puzzle-Defense has never been this fun and addicting! Defend your world from the invasion by building winding paths out of imaginative, new weapons. Over 20 new levels span the grassiest fields, driest deserts, sparkling cities, and even an infernal volcano lair! Are you ready to stop the Fieldrunners once and for all? Join the defense, now!' FROM games WHERE igdb_id = 9840 ON CONFLICT (game_id, language_code) DO NOTHING;
