INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('real-pool-3d-plus', 175307, '2012-03-31', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Pool 3D Plus', 'Challenge your friends to matches or play against the AI players in the best pool game. Real Pool 3D is one of the most realistic and enjoyable pool games available on mobile. It features many pool game modes like 8 Ball, 9 Ball, UK 8 Ball, Snooker, Time Trial, Matrix Mode and Practice Mode. So if you''re a billiards fan, there is something for you to play in Real Pool 3D. Customise your pool table by choosing the color and cloth patterns you like. In Time Trial you have a time limit of 4 minutes, in which you have to pocket balls as fast as you can to achieve more score. When you pocket more than one ball back to back, your multiplier will increase and which will boost your score and time. In Matrix Mode, when you pocket a ball your score will be multiplied by the difference of your previous and current ball number if the current is more than the previous; but if the current is less, then your score is divided by the current ball number. So be careful. Have you ever thought about playing billiards on a real table, Real Pool 3D is the perfect way to try a variety of games. Real life graphics and angles to help improve your skills. Play Practice mode if you just want to relax and play without any rules.' FROM games WHERE igdb_id = 175307 ON CONFLICT (game_id, language_code) DO NOTHING;
