INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unmechanical', 'Unmechanical is a puzzle adventure that combines tricky puzzle solving, alluring exploration, and an engrossing atmosphere. Set in a fantastic world of flesh, rock and steel, your journey to freedom requires you to solve a great variety of puzzling challenges, and while it’s easy to pick up and play, later challenges may prove very difficult indeed.' FROM games WHERE igdb_id = 16368 ON CONFLICT (game_id, language_code) DO NOTHING;
