INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Cthulhu: The Wasted Land', 'Call of Cthulhu: The Wasted Land is a turn-based strategy/role-playing game based on the award winning Call of Cthulhu RPG. Developed in conjunction with Chaosium and based their multi-award winning Call of Cthulhu RPG. Set in the midst of World War One, the game pits your team of investigators and soldiers against an ancient enemy, one older than humanity itself... Can your team of investigators keep their grip on sanity long enough to stop these diabolical plans?' FROM games WHERE igdb_id = 16667 ON CONFLICT (game_id, language_code) DO NOTHING;
