INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Really Big Sky', 'Way over in the big void of space live some aliens. They coveted your planet and would do anything to live there. So what''s your planet to do? Yeah, blast through them all! Face off against waves of enemies, bosses, giant laser planets, blackholes, wormholes, massive lasers, planets and asteroids across 12 game modes!' FROM games WHERE igdb_id = 10755 ON CONFLICT (game_id, language_code) DO NOTHING;
