INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carmen-sandiego-adventures-in-math-the-case-of-the-crumbling-cathedral', 51129, '2012-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pvu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nj7kxftjkljibqd00nz7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carmen Sandiego Adventures in Math: The Case of the Crumbling Cathedral', 'Carmen Sandiego is back and only you can foil her V.I.L.E plans. Travel the globe, solve brain-twisting math puzzles, and catch the villain behind the Crumbling Cathedral. Crack the case of the Crumbling Cathedral in single-player Story Mode. Perfect your math skills in single-player Practice Mode. Challenge your friends and family to solve math puzzles against the clock in Multiplayer Mode. In Carmen Sandiego Adventures in Math: The Case of the Crumbling Cathedral, you practice your math skills and use them to fight crime. Ideal for grades 4-5, math topics include arithmetic, logic puzzles, fractions and much more!' FROM games WHERE igdb_id = 51129 ON CONFLICT (game_id, language_code) DO NOTHING;
