INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Story', 'Build a glorious kingdom, filled with breathtaking fantasy buildings, heroes and villains, and adorable animals. Explore the mysterious forest, raise animals, and battle monsters in an epic adventure! Seize your destiny! Rule the kingdom you build! - CRAFT Castle Gates, Wizard Towers, magic potions and more inside your crafting workshops! - DECORATE your kingdom with walls, gates, towers, topiaries and more! - EXPLORE the mysterious forest surrounding your kingdom and rescue those who are trapped by the evil curse. - GROW crops to use in your kitchen for making feasts! - Invite your Facebook or Storm8 friends to play with you, and help each other grow your kingdom! - FREE updates will introduce new characters to discover, buildings to construct and more!' FROM games WHERE igdb_id = 79809 ON CONFLICT (game_id, language_code) DO NOTHING;
