INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Black Ops - Declassified', 'Before the future could be won, history had to be written. Exposing that story exclusively on PlayStation Vita, Call of Duty: Black Ops Declassified explores original fiction in the Call of Duty Black Ops universe with an all-new campaign of Special Ops missions. Optimized for gamers on-the-go, Call of Duty Black Ops: Declassified delivers the most intense handheld Call of Duty experience to date, including both Special Ops Story mode and Multiplayer combat tailored for the PS Vita.' FROM games WHERE igdb_id = 8548 ON CONFLICT (game_id, language_code) DO NOTHING;
