INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Loves Angela', 'There are a series of actions you can perform such as singing, giving a gift to Angela, or throwing a pot plant at Tom. You can tap either of the cats in different places to get different responses. As before, you can record actions and speaking in Tom Loves Angela and play it back to relive the fun.' FROM games WHERE igdb_id = 347068 ON CONFLICT (game_id, language_code) DO NOTHING;
