INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vubu', 175754, '2012-07-05', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vubu', 'The Vubu sky sanctuaries are overrun with a terrible curse and must be evacuated. Guide the Vubu to the portals while keeping them away from traps and ledges. There''s one catch - they all move in unison! Careful positioning is required and each Vubu type has its own unique traits. Vubu is a logic puzzle game that involves sliding pieces together towards the goals. Each board or level is a small maze that floats in the sky and the pieces can be lost if they fall off the edge or land on a trap. Be sure to take advantage of each Vubu''s special abilities. They can either help or get in the way.' FROM games WHERE igdb_id = 175754 ON CONFLICT (game_id, language_code) DO NOTHING;
