INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prototype 2: Limited Edition', 'Prototype 2 is an open-world action game and a direct sequel to Prototype. It was announced at the 2010 Spike Video Game Awards. The events of Prototype 2 takes place in New York City, now known as New York Zero (NYZ), following Sgt. James Heller on his quest to destroy Alex Mercer, after having lost everything and everyone he loved to the Blacklight virus Prototype 2: Limited Edition includes: A copy of Prototype 2 Exclusive behind the scenes DVD Exclusive flesh cleaver animation An Xbox avatar' FROM games WHERE igdb_id = 387192 ON CONFLICT (game_id, language_code) DO NOTHING;
