INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'May''s Mysteries: The Secret of Dragonville', 'May''s Mysteries: The Secret Of Dragonville is an exciting puzzle adventure. Follow May, an intelligent and charismatic girl, in her quest to find her missing brother. Advance through the adventure by solving over 270 logic puzzles, tricky rhythmic games and hand drawn hidden object scenes. Search for clues about May''s brother, visit mysterious locations and meet interesting characters along the way, which will help you in your journey.' FROM games WHERE igdb_id = 17928 ON CONFLICT (game_id, language_code) DO NOTHING;
