INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Fusion Generation', 'Fan-made Pokémon game that introduces the possibility of fusing two or more monsters to obtain a new creature. The games is a sort of "hybrid" in the Pokémon series: it takes many elements from the different episodes and merges them together. Made with RPG Maker XP (and Pokémon Essentials starter kit) by Matt Martin, Eric Davidson et al. [This game is no longer available at Nintendo''s request]' FROM games WHERE igdb_id = 18704 ON CONFLICT (game_id, language_code) DO NOTHING;
