INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Jack', 'Dynamite Jack must blast his way to freedom! Jack, a brave space marine, armed with only bombs and a flashlight, must escape the Anathema Mines! Use stealth to sneak past guards and bombs to obliterate enemies in this intense top-down action-adventure.' FROM games WHERE igdb_id = 15161 ON CONFLICT (game_id, language_code) DO NOTHING;
