INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Creepypasta Land', 'Creepypasta Land is a survival horror and psychological horror game made in RPG Maker VX Ace. The game was created by Lucas Boato, a Brazilian. In Creepypasta Land, the protagonist moves with his mother to Crelles Town and lives in a large house. There the protagonist ends up meeting with several creepypastas monsters and must survive them all, while making friends along the way.' FROM games WHERE igdb_id = 130346 ON CONFLICT (game_id, language_code) DO NOTHING;
