INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man', 'The Amazing Spider-Man is an action-adventure video game released in 2012, developed by Beenox and published by Activision. The game serves as a tie-in to the 2012 film of the same name, though it features its original storyline that continues after the movie''s events. Players control Spider-Man as he swings through an open-world version of New York City, battling criminals and iconic villains like the Lizard and Rhino while facing Oscorp''s mutated creatures. The game focuses on Spider-Man''s web-slinging, combat, and exploration abilities. It has a mix of main missions and side activities. The gameplay includes stealth, brawler-style combat, and environmental puzzles.' FROM games WHERE igdb_id = 1376 ON CONFLICT (game_id, language_code) DO NOTHING;
