INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bridge Constructor: Playground', 'Bridge Constructor Playground offers people of all ages an introduction to the topic of “bridge building”. This game gives you the freedom to let your creative side run riot – nothing is impossible. Across 30 innovative levels you have to build bridges over deep valleys, canals or rivers. Following this your bridges will be subjected to a stress test to see whether they can support the weight of the cars and/or trucks which drive across them.' FROM games WHERE igdb_id = 17098 ON CONFLICT (game_id, language_code) DO NOTHING;
