INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Dragon Side Story', 'Set on the mysterious planet Draco, "Crimson Dragon: Side Story" is a shooter in which you control dragons to defeat enemies. Use touch controls to pilot your dragon and target enemies--it''s a perfect match for your Windows Phone 7! Breed new controllable dragons, level up through repeated play, and choose from more than 170 skills to customize their attacks. Begin your journey on Draco today!' FROM games WHERE igdb_id = 79815 ON CONFLICT (game_id, language_code) DO NOTHING;
