INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wrc-3-fia-world-rally-championship', 43037, '2012-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30zw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tw5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WRC 3: FIA World Rally Championship', 'The official video game of the 2012 FIA World Rally Championship (WRC), WRC 3 marks a radical departure from the previous titles and sees the team using a completely new graphics and game engine, developed in-house, in order to bring the most advanced WRC driving experience to players. WRC 3 features all the rallies in the 2012 WRC calendar, complete with all leading WRC teams and drivers in the revamped career mode.' FROM games WHERE igdb_id = 43037 ON CONFLICT (game_id, language_code) DO NOTHING;
