INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 13', 'The world''s #1 selling golf game is back and ready for another season of PGA Tour golf. Take your game to the next level with the first controller-free, voice-enabled and body tracking sports simulation to support the Kinect sensor for Xbox 360 (optional and sold separately). Put real-life swing in-game with Tiger Woods PGA Tour 13 as you experience revamped swing control, tackle Tiger Woods'' legacy and compete against the world''s best players at The Masters.' FROM games WHERE igdb_id = 5226 ON CONFLICT (game_id, language_code) DO NOTHING;
