INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunted Memories', 'Haunted Memories is a first person adventure horror game inspired by popular ‘slender-genre’. Don’t be afraid – artistic part of Haunt isn’t the only one thing that makes this game unique. Provided story and whole ‘GreenPark’ proves, that Haunts vision of “Slender-Man” is deeper than ever before.' FROM games WHERE igdb_id = 16552 ON CONFLICT (game_id, language_code) DO NOTHING;
