INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mass Effect 3: N7 Digital Deluxe Edition', 'The N7 Digital Deluxe Edition contains: - Mass Effect 3 - N7 Arsenal pack and in-game items (N7 Crusader shotgun, N7 Hurricane submachine gun, N7 Valiant Sniper, N7 Eagle handgun, N7 hoodie) - Downloadable Art book and lithograph - Mass Effect Digital Comic by Dark Horse Comics - From Ashes DLC' FROM games WHERE igdb_id = 202174 ON CONFLICT (game_id, language_code) DO NOTHING;
