INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('c64anabalt', 41017, '2012-01-06', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ai2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'C64anabalt', 'C64anabalt is an official conversion of Adam Atomic & Danny B.''s award winning single-button 2009 indie game Canabalt for the 8-Bit, 64KB RAM, 1Mhz Commodore 64 home computer developed by Paul Koller (Paulko64). This particular version was designed to run from a 16KB cartridge (although there are also tape and disk versions available to download as well). The game was developed as an entry for the RGCD C64 16KB Cartridge Game Development Competition (2011), and the name C64anabalt was suggested by Adam Atomic himself. The physics and procedural algorithms are based on those documented in the original game''s open source code. There are two versions of C64anabalt available; one with a SID chip conversion of Danny B.''s original score by Mikkel Hastrup (Encore), and an alternative build featuring music from the PC indie game ThrustBurst by Andreas Slotte (Ghormak). Unfortunately it wasn''t possible to fit them both into a single 16KB ROM, so we''ve made two versions available to order (more on that in a bit) or download.' FROM games WHERE igdb_id = 41017 ON CONFLICT (game_id, language_code) DO NOTHING;
