INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naval War: Arctic Circle', 'Naval War: Arctic Circle is a Real Time Strategy (RTS) game where the player battles enemy naval and aerial forces for power and ultimate world domination. The game includes real units from the United Kingdom, Germany, the United States, Russia, the Scandinavian countries and others. The game play takes place along the Norwegian and British coast, through Iceland and Greenland all the way to the North Americas and the North West Passage.' FROM games WHERE igdb_id = 2044 ON CONFLICT (game_id, language_code) DO NOTHING;
