INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tokyo-babel', 11653, '2012-08-31', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44px.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2c1d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Babel', 'The gates of Heaven are closed shut; the realm of Hell consumed by flood. And in their wake, countless parallel worlds wither away, one after another. The surviving angels and demons gather at the city they believe to be their final chance at salvation: the floating purgatory of "Tokyo Babel". Joined by humans, they embark on a pilgrimage across the seven layers of Babel, hoping to ascend Jacob''s Ladder in an effort to re-open the gates of Heaven. Their journey would be an atonement toward the heavens. And yet, their plans fall into ruin as a group of pilgrims -- their minds consumed by madness - set out to lord over the numerous layers of Tokyo Babel with the intention to wreak complete and utter havoc atop the floating purgatory. Amidst this neverending impasse, a lone youth is saved from the ruins of his devastated world - Tendou Setsuna, a man denied human treatment since birth. Joining his savior, Lilith - known as the Witch of the Night, he begins his journey across Tokyo Babel... ...yearning for an answer to a single question: Why he still possesses the will to keep on living.' FROM games WHERE igdb_id = 11653 ON CONFLICT (game_id, language_code) DO NOTHING;
