INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairy Well', 'The forest has lost its four Princesses to the Dark Wizard of the Underground.  Each Princess has been locked in with three magic crystals. Find the first three crystals scattered in the cave and then head for the Well!  Fairy Well is a unique and ambitious flick-screen collect-em-up arcade adventure of epic proportions squeezed into a tiny 16KB of ROM space.  With its multiple game modes (via a character selection at the beginning of your quest), huge randomly generated level maps, varied enemies and items, boss-battles and timeless adventure gameplay, Fairy Well is a modern C64 classic. Guide your fairy through the labyrinthine underworld on your quest to rescue the captured princess and restore peace to the forest!' FROM games WHERE igdb_id = 41165 ON CONFLICT (game_id, language_code) DO NOTHING;
