INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mugen Souls', 'Mugen Souls is an RPG developed by Compile Heart with collaboration from GCREST. The main protagonist of Mugen Souls, Chou-Chou, plans to conquer the universe by subjugating the seven worlds it comprises, as she thinks the planets look pretty. Gameplay revolves around exploration and turn-based, open-field combat, and the game also includes mini games and customization. Due to the questionable nature of the game''s portrayal of child protagonists, certain aspects of the western release have been edited and some mini-games have been disabled.' FROM games WHERE igdb_id = 11501 ON CONFLICT (game_id, language_code) DO NOTHING;
