INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Land', 'Nintendo Land is a fun and lively virtual theme park filled with attractions based on popular Nintendo game worlds. Explore the Nintendo Land Plaza as your Mii character, and play in park attractions featuring unique and innovative gameplay made possible by the Wii U GamePad controller. Enjoy team, competitive, and solo gameplay experiences for up to five players!' FROM games WHERE igdb_id = 2172 ON CONFLICT (game_id, language_code) DO NOTHING;
