INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slender Rising', 'Slender Rising is a 2012 horror and indie mobile game by Michael Hegemann. It is based on the creepypasta called Slender Man, a tall, faceless man who hunts people down and inspired by the PC game Slender: The Eight Pages. The first-person game tasks players with collecting notes across various maps whilst trying to avoid the Slender Man.' FROM games WHERE igdb_id = 95676 ON CONFLICT (game_id, language_code) DO NOTHING;
