INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cho~ricchi! Tamagotchi no Puchi Puchi Omisecchi', 'Cho~ricchi! Tamagotchi no Puchi Puchi Omisecchi is a Nintendo 3DS game released exclusively in Japan on April 19, 2012. It is a remake of the original Corner Shop game remade with characters from the Tamagotchi! anime, and 3D graphics.' FROM games WHERE igdb_id = 77628 ON CONFLICT (game_id, language_code) DO NOTHING;
