INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cortex-command', 10428, '2012-09-28', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eiu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aresk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cortex Command', 'In the world of Cortex Command, many humans have opted to amputate their entire natural bodies in order to prolong their lives and enable interstellar space travel. Their disembodied brains are hardly helpless, however, as they can remotely control all kinds of machines and craft through artificial interfaces. Playing as one of these people''s brains, you can quickly switch control between many different expendable bodies in order to complete otherwise dangerous tasks - all from the physical safety of your command bunker. Use these technological powers of telepathy to collect gold out of the fully destructible terrain, then purchase even more bodies and materiel with those newly acquired funds! You can even program the crude A.I.s of your puppet army to complete simple tasks (patrolling, digging, etc.) while your attention and direct control is somewhere else. Use your accumulated forces to protect your brain, explore the world, and defeat your competition!' FROM games WHERE igdb_id = 10428 ON CONFLICT (game_id, language_code) DO NOTHING;
