INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supermagical', 'Welcome to the incredible world of Supermagical, where bubble-popping has never been so much fun! Supermagical is an awesome fun puzzle and adventure game for all ages, where you’ll visit tons of magical places, meet cool characters, and cook amazing spells. The game was selected as Game of the Week and among the Best of the Year on the App Store 2012. It has more than a million downloads.' FROM games WHERE igdb_id = 14714 ON CONFLICT (game_id, language_code) DO NOTHING;
