INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Mystery Dungeon: Gates to Infinity', 'Discover the incredible 3D world of Pokemon Mystery Dungeon: Gates to Infinity, where Pokemon speak and amazing adventures are always nearby! What''s more, you will become a Pokemon yourself! You''ll meet all kinds of Pokemon throughout the game, both in the towns you''ll visit and the Mystery Dungeons you''ll explore.' FROM games WHERE igdb_id = 4566 ON CONFLICT (game_id, language_code) DO NOTHING;
