INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total War Battles: Shogun', 'Specifically developed for touchscreen platforms, Total War Battles: Shogun is a real-time strategy game from the makers of the award-winning Total War series.  Total War Battles delivers quick-fire, tactical combat balanced with intuitive building and unit management. All set in a beautifully illustrated Medieval Japan.' FROM games WHERE igdb_id = 15318 ON CONFLICT (game_id, language_code) DO NOTHING;
