INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza 5', 'Yakuza 5 is an open-world action-adventure game and the fifth main title in the Yakuza series developed by Sega. For the first time in the series, it features five settings across Japan along with five playable main characters. The game also features a brand new graphics engine, unlike previous games in the series that have been re-utilizing the same engine since Yakuza 3.' FROM games WHERE igdb_id = 2063 ON CONFLICT (game_id, language_code) DO NOTHING;
