INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE ''13', 'WWE ''13 is a professional wrestling video game developed by Yuke''s and published by THQ for the PlayStation 3, Wii, Xbox 360. It is the sequel to WWE ''12. The game focuses on the Attitude Era of the WWF, replacing its Road to WrestleMania Mode with an Attitude Era Mode where the player plays through the Attitude Era. The game gives such characters as Stone Cold Steve Austin and elements as the Monday Night Wars a more important role in the game than in any previous WWE game.' FROM games WHERE igdb_id = 5295 ON CONFLICT (game_id, language_code) DO NOTHING;
