INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sugar Cube: Bittersweet Factory', 'Sugar Cube: Bittersweet Factory is a 2D platformer game that presents the story of a sugar cube. The background tiles of the game have two sides, namely, the front and the back. These tiles can be flipped for access to critical hints to solve different levels. They may or may not help you, so pay attention!' FROM games WHERE igdb_id = 15304 ON CONFLICT (game_id, language_code) DO NOTHING;
