INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schlag den Raab: Das 3. Spiel', 'Are you ready for high voltage and thrills of the extra class? Then Schlag den Raab: Das 3. Spiel is just right for you, because it brings the atmosphere of the popular TV show directly into your living room! Compete alone or with up to eight players against Stefan Raab or your friends. Compete in numerous original quiz and action games from the TV show. New questions, new games, old rules: Beat Raab!' FROM games WHERE igdb_id = 86078 ON CONFLICT (game_id, language_code) DO NOTHING;
