INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wooden Sen''SeY', 'Wooden Sen''SeY is an action-platformer, set in a unique "Japan Steam Rock" universe filled with humour. You follow Goro, a village chief, as he seeks revenge through a variety of levels. He will defeat his enemies using his axes to slice, dice, squash and grapple! Wooden Sen''SeY seeks to offer players a unique gaming experience, inspired by old school gameplay mechanisms, while incorporating contemporary technology and beautiful 3D graphics.' FROM games WHERE igdb_id = 10341 ON CONFLICT (game_id, language_code) DO NOTHING;
