INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Etrian Odyssey IV: Legends of the Titan', 'For centuries, the tree Yggdrasil has been a constant presence in the lives of the people of Tharsis. It looms on the horizon, visible from everywhere in the city. But its roots are in a far-off land where no one has ventured until the Outland Count of Tharsis sponsors an Explorers Guild to reach Yggdrasil and discover its secrets. You are the latest explorer arriving in Tharsis to seek your fame and fortune. Board your skyship and set out into the clouds in search of treasure, glory, and the answer to Tharsis'' oldest mystery.' FROM games WHERE igdb_id = 6767 ON CONFLICT (game_id, language_code) DO NOTHING;
