INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('foreign-legion-multi-massacre', 9844, '2012-07-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2i6i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl09.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foreign Legion: Multi Massacre', 'Foreign Legion: Multi Massacre is the (far too) long awaited follow up to Buckets of Blood. Now you can continue the cartoon-style third person battle online and battle your friends, enemies or even frenemies across 6 maps and various modes. Reduce the never-ending army of a non-descriptive country to a bloody, meaty pulp (with extra zest!) as legionnaires of an even less described country.  So what are you waiting for, get ready to make mince meat of other players, battle endless forces, determine the biologic equation, host a nice pick nick or swim in the ocean.  Now With Zombie Mode:  After having a fun and merry undescribed time in the woods, the legionnaires need a Helicopter ride home. They discover a creepy cabin in the woods(TM) and decide to call a helicopter. Whilst summoning the helicopter, they accidentally summoned the evil forces of hell as well! Fend of hordes of zombies while keeping the generator running, powering the lights and the signal to the helicopter. It wouldn''t be a FL map without our signature humour so expect some unusual zombies, crazy environments, a ton of destructables, easter eggs and buckets of GORE. Who can get the highest body count?' FROM games WHERE igdb_id = 9844 ON CONFLICT (game_id, language_code) DO NOTHING;
