INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shellrazer', 'You are a Klang Clan Turtle Wrangler and you must ensure your War Turtle completes his annual trek across the Goblin Kingdoms. Battle hordes of goblin archers, ballooners, sheep riders, mutant monsters and steampunk war machines and collect their loot to keep your edge in battle.' FROM games WHERE igdb_id = 214670 ON CONFLICT (game_id, language_code) DO NOTHING;
