INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nihilumbra', 'Nihilumbra is played as a standard platform game, by controlling Born as he walks and jumps across the game''s levels. There are multiple enemies that the player needs to avoid since, at first, there is no way to defeat them. The game is divided into the five worlds that Born explores. In each of them, the player is granted a new colour, with which the player can paint on the terrain (by touching the screen) to modify the behaviour of the environment.' FROM games WHERE igdb_id = 3026 ON CONFLICT (game_id, language_code) DO NOTHING;
