INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: Tomb of the Lost Queen', 'Enter the Cursed Tomb of the Lost Queen! Egyptologists and archaeologists are abuzz about recent discoveries by a university dig team, but suspicious accidents left the group isolated and leaderless. Is a curse burying their progress or is someone sabotaging their success? Find out as you assume the role of Nancy Drew and uncover the lost secrets buried within the Tomb of the Lost Queen!' FROM games WHERE igdb_id = 10587 ON CONFLICT (game_id, language_code) DO NOTHING;
