INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ichi', 'Ichi is an easy to play but challenging one button puzzle game. Don''t be deceived by the game simplistic look, it’s a braintwister for sure! Collect golden rings by rotating objects, using teleporters, breaking blocks and more. If that isn’t enough, the game includes a level editor that allows you to create your own levels and share them with anyone around the globe!' FROM games WHERE igdb_id = 8953 ON CONFLICT (game_id, language_code) DO NOTHING;
