INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oil Rush', 'Oil Rush is a naval strategy game that takes place in a world where nuclear war has melted the ice caps, changing the face of the planet forever. Oil Rush offers unique gameplay, avoiding micromanagement of every single unit, while still providing full control over all important aspects of strategy and economy.' FROM games WHERE igdb_id = 1054 ON CONFLICT (game_id, language_code) DO NOTHING;
