INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Closure', 'In the dark and mysterious world of Closure, only what you see exists. Manipulate lights to phase objects in and out of reality in this multiple-award-winning puzzle game. Play as a strange spider-like demon who explores the stories of three human characters through beautiful, eerie environments such as a decrepit factory, a murky forest, an abandoned carnival, and the strange, surreal realm that connects them together.' FROM games WHERE igdb_id = 8146 ON CONFLICT (game_id, language_code) DO NOTHING;
