INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guardians-of-middle-earth', 7892, '2012-12-05', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20ps.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wu898v6xzqxgk6oekh6q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardians of Middle-earth', 'A shadow grows over Middle-earth as the greatest armies of the Third Age prepare for the coming battle. Take up arms in the clash over Middle-earth as the most powerful heroes and villains from the greatest fantasy epic of all time.  Guardians of Middle-earth delivers an authentic multiplayer online battle arena (MOBA) game set in Middle-earth! Play with friends to bring up to 10 players together in strategic five versus five competitive multiplayer battle arenas in this epic setting. Call upon legendary heroes and villains from The Lord of the Rings and The Hobbit as you form memorable alliances in this truly groundbreaking MOBA experience!  Guardians of Middle-earth was one of the many games afflicted by the GameSpy server shutdown.' FROM games WHERE igdb_id = 7892 ON CONFLICT (game_id, language_code) DO NOTHING;
