INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waking Mars', 'Waking Mars is a one-of-a-kind adventure in which you jetpack through subterranean Mars encountering a host of extraordinary alien lifeforms that operate as a living, breathing ecosystem. Learn and master the behaviors of these creatures to create ecosystems of your own design if you are to survive and discover the secrets of Mars'' past.' FROM games WHERE igdb_id = 14722 ON CONFLICT (game_id, language_code) DO NOTHING;
