INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny Arcade''s On the Rain-Slick Precipice of Darkness 3', 'The Startling Developments Detective Agency springs into action as On the Rain-Slick Precipice of Darkness 3 begins, set in motion by a call from a mysterious source. The ever escalating perils on the Rain-Slick Precipice of Darkness will season our tender heroes to their very core! Expect cunning evil doctors, a series of unexplainable thefts, a mysterious book of power, enigmatic supernatural forces, hoboids, roboids, time travelling dinosaurs, and more.' FROM games WHERE igdb_id = 14980 ON CONFLICT (game_id, language_code) DO NOTHING;
