INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krater: Shadows over Solside', 'Krater is a real-time squad based dungeon crawling game. The game combines fast paced combat, tactical squad management, crafting, and questing all seen from a classic RTS perspective.  While the game’s campaign can be played offline, the Co-Op expansion adds the opportunity to tackle hours of specially designed online Co-Op dungeons and bosses.  The game brings you far into the future of a post-apocalyptic Sweden. Once home to IKEA, Vikings, and Minecraft, today its primitive inhabitants scavenge the broken overgrown world for technological artifacts.' FROM games WHERE igdb_id = 2020 ON CONFLICT (game_id, language_code) DO NOTHING;
