INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '99 Spirits', '"99 Spirits is an RPG/Puzzle game that revolves around the popular Japanese folklore of Tsukumogami, everyday objects coming alive on their 100th birthday. The Game Features an original battle system where players will have to puzzle out the true identity of the enemy before defeating them. We would love for you to experience this unique system not found in any other game. 99 Spirits is the first RPG produced by the Japanese indie game circle TORaIKI" Fruitbat Factory also published the original Japanese version on Steam and it is included in the purchase of the translated game.' FROM games WHERE igdb_id = 9937 ON CONFLICT (game_id, language_code) DO NOTHING;
