INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero of the Kingdom', 'Hero of the Kingdom is casual role-playing game at its best; take to the road and explore a vast and beautiful country full of danger and surprises. Meet and interact with characters to gain knowledge and insight giving you valuable clues. Defend against and attack the enemy, and take it upon yourself to complete quests of varying difficulty. To survive, you must find ways to earn gold by mastering your skills and bartering. You can even collect herbs, hunt for animals, and go fishing.' FROM games WHERE igdb_id = 9638 ON CONFLICT (game_id, language_code) DO NOTHING;
