INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: Operation Raccoon City', 'Resident Evil: Operation Raccoon City is a third-person shooter and is a spin-off of the long-running Resident Evil series. Unlike the main games in the series, it is less of a survival horror game and more of an action-packed shooter. The game includes twelve playable characters, however the players can choose only four characters for the online modes. Each team member has their own special role and abilities.' FROM games WHERE igdb_id = 977 ON CONFLICT (game_id, language_code) DO NOTHING;
