INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colour Bind', 'Colour Bind is a physics platform-puzzler set in an abstract world where gravity is determined not by mass, but by colour. Navigate this unique world by manipulating colour and gravity to solve each level. Beating each unique puzzle in Colour Bind will take patience, intelligence, quick reflexes and sometimes even a helping hand from a friend.' FROM games WHERE igdb_id = 10101 ON CONFLICT (game_id, language_code) DO NOTHING;
