INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('roller-coaster-rampage', 16359, '2012-05-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/sxegqyu4lc3ps0aiczvb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/d5wtcoxaidqdd1molkpe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roller Coaster Rampage', 'Roller Coaster Rampage is a fast paced, high-scoring, competitive rollercoaster simulator with destructive environments! Players compete to perform the best manual maneuvers, collect the most gems, link to the most track sections, and gain first place on the leaderboards! Roller Coaster Rampage revolutionizes the coaster genre by introducing on-the-fly track construction and deformation. In previous games the coaster riding experience was a passive, non-interactive experience. Roller Coaster Rampage introduces an innovative approach, and a specialized procedural coaster engine that allows players to build coasters in real-time as they ride them. Players leave behind a trail of procedurally-generated coaster tracks and supports, which then become obstacles as the player circles back.' FROM games WHERE igdb_id = 16359 ON CONFLICT (game_id, language_code) DO NOTHING;
