INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puddle', 'Dive into Puddle, a game unlike any other where you have to guide a puddle of fluid by tilting the environment to the left or right! Play carefully taking friction, gravity and temperature into account, and by using the unique properties of each type of fluid (water, oil, nitroglycerin, molten lava...) in a range of original environments. Conserve as much fluid as possible when crossing a variety of obstacles such as burning passageways, carnivorous plants and electric currents!' FROM games WHERE igdb_id = 10728 ON CONFLICT (game_id, language_code) DO NOTHING;
