INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shoot Many Robots', 'The title sums it up pretty well, but if you still need convincing: A 4-player co-op run-n-gun action shooter that throws you into a tidal wave of degenerate robots with an array of weaponry that would make any mama proud. A classic 2.5D side-scrolling shooter, revitalized with modern game design.' FROM games WHERE igdb_id = 11643 ON CONFLICT (game_id, language_code) DO NOTHING;
