INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'iBomber Defense Pacific', 'iBomber moves to the Pacific as you fight a whole new enemy across the Pacific rim to regain freedom. iBomber Defense Pacific takes tower defense to a whole new level and makes you feel like you''re right there and part of the incredible action. iBomber Defense Pacific has all-new tactics, all-new strategies, all-new maps, all-new weapons and all-new enemies.' FROM games WHERE igdb_id = 9288 ON CONFLICT (game_id, language_code) DO NOTHING;
