INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QP Shooting: Dangerous!!', 'QP Shooting - Dangerous!! is a bullet hell type shoot''em''up starring the pudding-loving dog girl QP seen in 100% Orange Juice. Nothing can stand between QP and her pudding - not even difficulty options to reduce the experienced gamer to tears! The game has 5 stages and 4 difficulty levels, as well as 3 styles to chose from that affect the use of your hyper mode in-game. It also has an arcade and a conquest mode, which allows you to save after each stage.' FROM games WHERE igdb_id = 11569 ON CONFLICT (game_id, language_code) DO NOTHING;
