INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girls Like Robots', 'Their faces are the playing pieces. The rules are their emotions! Ridiculously charming puzzles, wrapped around an epic tale of love and danger, topped off with an authentic old-time stringband soundtrack! The goal is to put every one next to their friends. But you can''t please everybody all the time. Sometimes you gotta break hearts to save the day. And the day definitely needs saving: Volcanoes, exploding chickens, planetary invasion and a boy who just wants to dance with a girl.' FROM games WHERE igdb_id = 16841 ON CONFLICT (game_id, language_code) DO NOTHING;
