INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance: Crossfire', 'Jagged Alliance: Crossfire is a stand-alone expansion to the hit tactical RPG - Jagged Alliance: Back in Action. Crossfire adds new mercenaries, new environments and new weapons to challenge the player''s battlefield planning skills, while offering the combination of humorous dialog and realistic combat fans have come to expect from the series'' decade-long history.' FROM games WHERE igdb_id = 10467 ON CONFLICT (game_id, language_code) DO NOTHING;
