INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nightmares-from-the-deep-the-cursed-heart', 16779, '2012-04-19', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21os.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpu5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmares from the Deep: The Cursed Heart', 'You are a museum owner pursuing an undead pirate who kidnapped your daughter. You quickly realize that the villain is entangled in a tragic, centuries-old love story, and wants to resurrect his mistress with the girl’s life force. You feel sorry for the pirate, but you have to stop him before it is too late for your daughter… You will leave the modern museum quickly, and find your way to rundown pirate settings, all of them three centuries old. Since the time of the golden age of piracy, the locations have become neglected, deserted and overgrown with plants. Full moon, bones laying on the ground, and a skull-shaped rock add to the dark atmosphere of the mysterious island. What tragic events took place on the island before your arrival? What evil powers can make an old, rotting ship sail? Is the horrifying, undead pirate really as evil as he seems?' FROM games WHERE igdb_id = 16779 ON CONFLICT (game_id, language_code) DO NOTHING;
