INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('towns', 28041, '2012-11-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rq8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/oqfaxjjhailvvwa48nzf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towns', 'This game was released in 2012 on Steam through Steam Greenlight while still in its beta. The developers decided to abandon its development in 2014, leaving the game in an unfinished state but available for purchase. "The game brings a fresh new take on the city building/management genre by introducing many RPG features. In Towns you manage a settlement on top of an active dungeon. Instead of playing the hero who delves deep into the dungeon, how about playing the town that houses and caters to the hero''s needs? Both the RPG and strategic aspects will be fleshed out over a series of sprawling dungeons. Attract travelling heroes that will independently explore the dungeons below, fight off monsters, gain levels, special skills and collect the best loot they can find in order to clear the land of all evil! Craft unique weapons, trade with exotic items, obtain randomized loot, set up devious death traps and build a settlement capable of holding back the forces that come up from the depths!"' FROM games WHERE igdb_id = 28041 ON CONFLICT (game_id, language_code) DO NOTHING;
