INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warp', 'Warp is a strategic stealth-action puzzler where gamers play as Zero, a loveable yet lethal, little orange alien with a big score to settle. Abducted by a villainous General from his home world and taken to an underwater research facility, Zero must plan his ultimate escape by relying on his arsenal of special abilities.' FROM games WHERE igdb_id = 2347 ON CONFLICT (game_id, language_code) DO NOTHING;
