INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sol-exodus', 10886, '2012-01-25', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31c5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z4kprzcnh2lbkxthymbx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SOL Exodus', 'Eight epic missions take you across breathtaking landmarks of our solar system, including Pluto, Neptune, Triton, Uranus, Saturn, and Titan. SOL: Exodus is a 3D space-action game that leverages the power of the Unreal Engine to deliver epic space battles featuring enormous capital ships, hordes of spacecraft, and beautifully rendered planetary battlegrounds in an actionpacked, cinematic presentation reminiscent of TV shows and movies. In the world of SOL, 500 years in the future, the Earth that we know and love has been ruined by centuries of war, neglect and abuse, and humanity has left it behind as they colonized the solar system. Their thirst for conflict, however, followed them. It was only once scientists realized the sun was dying that man finally learned to work together. And work together they did - to form the United Colonies of Sol (UCS) and its UCS-1 Mission; the last hope for mankind.' FROM games WHERE igdb_id = 10886 ON CONFLICT (game_id, language_code) DO NOTHING;
