INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3switched', 9934, '2012-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ksf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl0w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3SwitcheD', '3SwitcheD combines classical Gameplay with fascinating new technologies. Find yourself in a new World arcade gaming. The brand-new 3D- and 3D-ET-Technology lifts the whole Game really in a new Dimension. Using the 3D-ET-technology 3SwitcheD not only gives you fantastic real 3D looks, it works 3D. Using any connected camera the game will scan your face and you will be able to turn the view only by looking in the direction you want it to! This brand new Technology will give you a Gaming experience never imagined! For all Players not using this feature the Game still provides fantastic looks and a bunch of challenges! A bunch of challenges is waiting for you, are you ready? Six highly addictive, vastly different and challenging modes set in an innovative 3D environment. Clear clusters and even shift gravity to rearrange gems for an all-new experience in puzzle and strategy gaming. Boost your high scores out of orbit with vertical, horizontal and even diagonal moves to blast those brilliant gems and gain access to the bonus levels!' FROM games WHERE igdb_id = 9934 ON CONFLICT (game_id, language_code) DO NOTHING;
