INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dyad', 9132, '2012-01-12', 88, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60jp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qhg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyad', 'Dyad is an arcadey tunnel racing puzzle game with a heavy emphasis on quick movement, reactive bright neon visuals, creating colorful music soundscapes, and sensory overload. Players are given the ability to "Hook" and "Graze" enemies in the tube to fill up their "Lance" meters, which they can expend to "Lance" enemies forming combos and increasing their momentum. Over the course of 27 levels the game introduces enemies with varying sets of characteristics, and items which can change the rules mid-game leading to mechanical complexity.' FROM games WHERE igdb_id = 9132 ON CONFLICT (game_id, language_code) DO NOTHING;
