INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BulletAsylum', 'BulletAsylum is an arcade shooter where players defend against waves of alien invaders using extensive weaponry. The game combines classic arcade mechanics with modern visuals, offering multiple game modes including Arcade, Survival, and Architect. Players can access dozens of weapon upgrades and game modifiers that alter gameplay rules. The game includes leaderboards for competitive play and features 200 Gamerscore worth of achievements.' FROM games WHERE igdb_id = 93506 ON CONFLICT (game_id, language_code) DO NOTHING;
