INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pettson''s Inventions 2', 'This is the sequel to the acclaimed Pettson’s Inventions app. Bigger, smarter and more fun than ever! Help old Pettson and his cat Findus build amazing inventions. Which objects should be included and what is their function? Drag the pieces to the right place and watch the spectacular invention take off! As usual, a secret awaits those who make it through. A fun and educational app that trains logic and stimulates creativity in children of all ages.' FROM games WHERE igdb_id = 56885 ON CONFLICT (game_id, language_code) DO NOTHING;
