INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazing Runner', 'Amazing Runner is a sleek and accessible endless-runner game set in a vibrant, futuristic universe. Players dash through dynamic tracks, leaping and sliding to evade obstacles, and enjoy standout mechanics like wall and ceiling running, alongside swirling corkscrew sections that demand precise circular swipes. With responsive controls and a variety of power-ups and avatars, the gameplay remains engaging and polished throughout. Critics generally considered the game "mixed or average": appreciated for its fun execution and inventive touches, yet seen as somewhat derivative compared to genre-defining titles.' FROM games WHERE igdb_id = 41510 ON CONFLICT (game_id, language_code) DO NOTHING;
