INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Overlord', 'Unite the stars under one galactic empire! Galactic Overlord is a simple yet addictive realtime strategy game in which you must conquer all the planets while rival AI players are trying to do the same! The are currently four play modes: Duel - battle an AI player for galactic supremacy! Three Way - battle two AI players at once! Cloaked - battle an AI player with invisible starships! Asteroids - like Duel, but with moving planets that require a more dynamic strategy!' FROM games WHERE igdb_id = 22003 ON CONFLICT (game_id, language_code) DO NOTHING;
