INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stormfall: Age of War', 'The lands of Darkshine are in turmoil, as rival Lords battle over the remnants of the once-great Empire of Stormfall. By the will of Lord Oberon, you have been chosen to fortify and expand your Castle, discover the mysteries of the Lost Arts, and build an army unrivalled since the days of old. You must master strategy, diplomacy, logistics and warfare as you forge alliances, join forces with great Leagues, and defeat your rivals.' FROM games WHERE igdb_id = 21677 ON CONFLICT (game_id, language_code) DO NOTHING;
