INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamworks Dragons: Wild Skies', 'Think you''ve got what it takes to be a rider of Berk? Put your skills to the test and blaze your own path as a dragon trainer. Explore the island, train wild dragons, and take flight in awesome aerial challenges! Ride the dragons you love from the movies: Gronckle, Deadly Nadder, Monstrous Nightmare, Hideous Zippleback, and Night Fury! Plus, watch for new dragon species from the series. Every time a new dragon appears in the show, you''ll be able to train it in the game!' FROM games WHERE igdb_id = 321022 ON CONFLICT (game_id, language_code) DO NOTHING;
