INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harley Pasternak''s Hollywood Workout', 'Developed by Heavy Iron Studios, Inc., Harley Pasternak''s Hollywood Workout integrates Harley''s renowned 5-Factor Fitness program which requires just 25 minutes a day, five days a week. Train with Harley in posh environments including a beach front condo, downtown Los Angeles loft, and a swanky Hollywood Hills home. Stay motivated by following your progress with the Fitness Tracker, a detailed calendar that tracks workouts, points earned per day, estimated calories burned, and time left in your program.' FROM games WHERE igdb_id = 50963 ON CONFLICT (game_id, language_code) DO NOTHING;
