INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kyokugen-dasshutsu-minigame-renda-shibou-desu', 298861, '2012-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co84a2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyokugen Dasshutsu Minigame: Renda Shibou Desu', '''Kyokugen Dasshutsu Minigame: Renda Shibou Desu'', translated roughly as ''Zero Escape Mini Game: Hit the Button to Kill'', was a small flash game hosted on Chunsoft''s Japanese website. The goal is to help Clover inside of a gate by rapidly clicking on the door. As the gate opens, the clicking action switches from opening the gate to seemingly groping/slapping Clover''s breasts. Three gates are presented, though Clover''s outfit changes depending on which gate the player is presented to open. The first gate''s outfit is her typical getup in Virtue''s Last Reward, the second is a sukumizu (スク水), and the third is a black bikini. The third gate is notably difficult and its reward is cut short by Clover covering up her nearly-revealed breasts while K''s portrait is laid over her face.' FROM games WHERE igdb_id = 298861 ON CONFLICT (game_id, language_code) DO NOTHING;
