INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lasting', 'Lasting is an interactive experiment in claustrophobia developed in 2012. The map and events generate randomly, so everyone''s experience is different. Gather disks and descend into the dizzying complex as the thick static presses in on you. You are not alone.' FROM games WHERE igdb_id = 126085 ON CONFLICT (game_id, language_code) DO NOTHING;
