INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby League Live 2', 'Rugby Leage Live 2 is a rugby simulation game in which players compete against real-world teams in realistic matches. It features a number of different game modes, including a career mode, custom matches and online games. There is also a Fanhub program in which a user can create and edit teams, players and competitions.' FROM games WHERE igdb_id = 41585 ON CONFLICT (game_id, language_code) DO NOTHING;
