INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('michael-schachts-web-of-power-card-game-the-duel', 175293, '2012-03-19', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michael Schacht''s Web of Power Card Game: The Duel', 'In Schacht''s Web of Power games you battle opponents across a landscape of 12th century Europe, trying to influence the great powers that rule the Dark Ages. The Duel Card Game depicts that conflict using a set of tiles that players will claim over the course of a game. By tactically placing ownership markers and taking tiles, you will achieve the majority control required to influence the countries and powers of Europe. Four different opponents, each with their own personality, challenge you at a variety of difficulty levels to make the game very replayable. Web of Power Card Game: The Duel is built on the same successful MobileEuroCard platform that was used to create Michael Schacht''s Gold and Reiner Knizia''s High Society, Kingdoms, Money, and Modern Art: The Card Game. Simple gestures allow you to take tiles and move markers. Everything is animated, for a colorful play experience. Previously released as the tabletop game Richelieu, The Duel has now returned to its intended Dark Ages theming.' FROM games WHERE igdb_id = 175293 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 175293 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
