INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LetterMeister', 'The language puzzle game for word lovers and language learners, playable with English words, French words, Spanish words or German words. Rearrange the letters in each grid using colour clues to form a set of interlocking words. Customise the game to your desired pace and vocabulary level. Remember to maximise your use of bonus squares while you attempt to beat the clock in later levels.' FROM games WHERE igdb_id = 173802 ON CONFLICT (game_id, language_code) DO NOTHING;
