INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Synesthetic', 'Experience your music like never before with Synesthetic, the first IOS game that truly syncs with your music. Embark on an out of this world rollercoaster ride, dodging obstacles and going though loops, trying to improve your highscore. Everything (the speed, obstacles and colors) is in tune to your music.' FROM games WHERE igdb_id = 175334 ON CONFLICT (game_id, language_code) DO NOTHING;
