INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jewel-link-galactic-quest', 269789, '2012-09-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3px.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxwjo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Link: Galactic Quest', 'It''s the year 3495 and your mission is to help Captain Smith of the Starship Victory on an intergalactic adventure to save the planets! A massive explosion has rocked the entire cosmos - a gigantic star has gone supernova, unleashing unimaginable destructive force on the galaxy''s citizens. The resulting wave of wreckage now threatens the existence of the entire universe. With 3 different ways to play and power-ups to collect, use your match-3 skills to search galactic locations and help destroy the space debris before it''s too late!' FROM games WHERE igdb_id = 269789 ON CONFLICT (game_id, language_code) DO NOTHING;
