INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phonopath', 'Phonopath is a puzzle game based entirely in audio. Each stage of the game is comprised of a sound clip and password request. The password lies hidden within the audio file itself, and can only be revealed through critical listening, careful analysis and manipulation. Phonopath aims to explore the limits of “the audio file as a puzzle medium”. Expect to learn something.' FROM games WHERE igdb_id = 282354 ON CONFLICT (game_id, language_code) DO NOTHING;
