INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('agarest-generations-of-war-2-collectors-edition', 42991, '2012-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zzl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ugdwonbdzxon6qfzcyns.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agarest: Generations of War 2 - Collector''s Edition', 'One day, the world was enveloped by a mysterious blinding light causing terrible destruction. The central continent, from where the light is believed to have originated from, went silent, while at the same time demons began to spread throughout the world like a plague. Sometime afterwards, a young man by the name of Weiss, suffering from amnesia, encounters the enigmatic Eva, from who Weiss learns that he has committed the sin of decide. In order to atone for his crime he must become the "Vessel" in which the power of the divinity he slaughtered will be stored. For that power will be used to resurrect the one whose life he stole. For those who betray the divine will pay for their sins in the space which separates salvation and damnation, as will their progeny... Revamped Battle System: Unlike the first two games of the series, Agarest 2 battles are fought with an engaging active grid-based battle system. HD graphics: Enjoy your favorite characters, environments and CGs in high-definition! Mini-games: Engage in PlayStation Move compatible Bathtub, Shiatsu, and Massage mini-games. New Agarest Universe: Roam freely in the newly designed world of Agarest. Collector''s Edition Contents: PS3 game / Double-sided inlay / 48-page hardback art book / 6 collectible art cards / A3 poster featuring / Aina & Victoria / Special slip case' FROM games WHERE igdb_id = 42991 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42991 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
