INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Layton Brothers: Mystery Room', 'Layton Brothers: Mystery Room is a Professor Layton series spin-off game for the iOS and Android mobile operating systems. It was announced on the LEVEL-5 Vision event 2011. The game follows Lucy Baker, a beginning detective who is transferred to Scotland Yard. Here, she works under Alfendi Layton, son of the renowned Professor Hershel Layton. Together, they investigate crimes for Scotland Yard''s "Mystery Room". The game was released as a freemium game: the game itself and the first 2 cases (and prologue) are free, while two additional packs of respectively 4 and 3 cases can be bought from within the app.' FROM games WHERE igdb_id = 20912 ON CONFLICT (game_id, language_code) DO NOTHING;
