INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madagascar: Join the Circus', 'The Madagascar troupe is performing center ring as they travel the world on their journey back home. Build up and decorate your wild Big Top attractions and clown around with Madagascar-style mini-games featuring Alex the Lion, Marty the Zebra, Melman the Giraffe, Gloria the Hippo, and all their new and old friends. Keep fans coming to your circus on the way back to New York!' FROM games WHERE igdb_id = 25186 ON CONFLICT (game_id, language_code) DO NOTHING;
