INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autumn Dynasty', 'Autumn Dynasty is a revolutionary new real time strategy game designed from the ground up for iPhone, iPad, iPod touch. With a unique drawing interface, players can paint their battle plans directly onto the map, using brush strokes to direct their armies, invoke powerful stratagems and conquer their foes! Defeat your friends and opponents from all around the world in an amazing online multiplayer mode.' FROM games WHERE igdb_id = 200286 ON CONFLICT (game_id, language_code) DO NOTHING;
