INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pin Tiki Ball', 'Pin Tiki Ball is a large scale cartoon physics game with fun features. Juggle the volcanic hot lava balls high and low, while protecting the Pin Tiki natives from Scorpions and Snakes. Crush and collect Coconuts, Watermelons and Bananas, find Diamonds, Rubies, Gold and activate the Bamboo Pipe Water Sprinkler to calm down the volcano''s wrath...' FROM games WHERE igdb_id = 87552 ON CONFLICT (game_id, language_code) DO NOTHING;
