INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Offroad Legends', 'Drive the most amazing offroad vehicles of all time in this extreme hill climbing madness! Crash the barriers and fly above bottomless chasms with Monster Trucks, 4x4 off-roaders and six-wheeled Behemoths! Use your best skills to beat the most mind blowing tracks and be the ultimate Offroad Legend!' FROM games WHERE igdb_id = 88984 ON CONFLICT (game_id, language_code) DO NOTHING;
