INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sbk-generations', 41582, '2012-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qps.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctqkl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SBK Generations', 'The official game of the Superbike FIM World Championship is back this year on PlayStation 3 and Xbox 360 with the most comprehensive motorcycling simulation of all time. Experience the last 4 seasons, including the new 2012 season, of the SBK world championship. Take the title of World Champion, take on the new SBK Experience mode and win the all-new single-maker races. With SBK Generations, Milestone is ready to release the definitive masterpiece of the motorcycling genre! OFFICIAL MODE: experience the thrills of the official Superbike championship! Race as the SBK, SuperSport and SuperStock 1000 riders on the most famous circuits in the world, and relive the history-making races of the 2009 to 2012 seasons. CARRIER MODE: take on the championships from 2009 to 2012 as your alter-ego, starting in the lower categories and going all the way to the premium class, where the World Champion title awaits. SBK EXPERIENCE: a unique and innovative experience that brings you into the heart of the world of motorcycling through thrilling themed challenges and single-maker races, against the best riders in the world, including the Legends. ONLINE: experience all the thrills of a real Superbike race, challenging up to 15 players online.' FROM games WHERE igdb_id = 41582 ON CONFLICT (game_id, language_code) DO NOTHING;
