INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Topps Bunt', 'Topps BUNT MLB Card Trader is the officially licensed digital collectibles app of Major League Baseball and MLB Players, Inc! Join a passionate community of baseball fans from around the world that enjoy collecting & trading Topps baseball cards, bringing their collections to life with fun, interactive in-app features! Set lineups using Topps baseball cards in your collection that score in real-time! Topps BUNT is the premiere trading card destination to collect favorite players, iconic moments, original art, classic Topps designs and more – all from your mobile device.' FROM games WHERE igdb_id = 79001 ON CONFLICT (game_id, language_code) DO NOTHING;
