INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FireJumpers', 'In this real-time strategy game, you command a team of elite firefighting helicopters, ground units and water bombers as they battle raging wildfires around the world. Your firefighters will leap into action against fires ranging from grass fires to town-threatening infernos. And the action continues as your team must battle fires in Central Park, the Everglades and even a volcano!' FROM games WHERE igdb_id = 200126 ON CONFLICT (game_id, language_code) DO NOTHING;
