INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frozen Hearth', 'Frozen Hearth is a Real-Time Strategy game, blended with exciting RPG features to create a new experience for lovers of RTS games. Set in our own unique, Dark-Fantasy world-setting, you can play alone, or co-operatively with a friend, through an epic and brutal campaign. Taking on the role of a powerful Avatar of the heroic, individualistic Danaan; you will try to save them from certain extinction at the hands of an immense horde of ravenous ice monsters – known as the Shangur –driven ever forward by an unstoppable wave of moving ice and snow that consumes everything it shrouds.' FROM games WHERE igdb_id = 8914 ON CONFLICT (game_id, language_code) DO NOTHING;
