INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzler World 2012 3D', 'With Puzzler World 2012 3D, players can collect trophies in a personal trophy cabinet as proof of skill, collect hint tokens for help on tricky clues and puzzles, and teach the game to remember individual letters and numbers using the handwriting recognition feature. Add more variety and hours of fun by unlocking bonus games with new modes. Take on additional bonus games such as Hangman, Chain Letters, Missing Piece, and more with Challenge mode. For an extra challenge, unlock Master mode puzzles to reveal a broad range of even tougher puzzles.' FROM games WHERE igdb_id = 47636 ON CONFLICT (game_id, language_code) DO NOTHING;
