INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danball Senki Baku Boost', 'Danball Senki Baku BOOST (ダンボール戦機 爆ブースト), localized as LBX: Little Battlers eXperience, is a Nintendo 3DS game for the Danball Senki game franchise. As of now, it is currently the only game in the franchise to get localized outside of Japan. The game is an improved remake version of the original Danball Senki game, with even more features continuing from Danball Senki BOOST.' FROM games WHERE igdb_id = 136914 ON CONFLICT (game_id, language_code) DO NOTHING;
