INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bluecoats: North vs. South', '1861. The Civil War has been declared in the United States. Two clans are fighting: The abolitionist Union and the pro-slavery Confederates. NORTH vs SOUTH is inspired from THE BLUE COATS comic book. You''ll relive the biggest events of this battle with Sergeant Chesterfield and Corporal Butch.' FROM games WHERE igdb_id = 24232 ON CONFLICT (game_id, language_code) DO NOTHING;
