INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undead Syndrome Episode 1', 'In The Undead Syndrome, players assume the role of a nameless, amnesiac woman who is stabbed and killed while walking through a desolate street during the daytime. She soon awakens only to find herself unceremoniously transported into a haunted house. Unable to distinguish nightmare from reality, the woman vows to unravel the facts in relation to her death and murderer.' FROM games WHERE igdb_id = 152019 ON CONFLICT (game_id, language_code) DO NOTHING;
