INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunt', 'Welcome to Benjy''s Mansion - a spooky haunted house where you are the first visitor for a generation! Haunt leverages the power of Kinect to enable you to freely explore the house using just your body as the controller - you''ll need to stay on your toes in order to outsmart the mansion''s host of fiendish ghosts and unravel the sinister secrets that shroud the mansion in mystery!' FROM games WHERE igdb_id = 20245 ON CONFLICT (game_id, language_code) DO NOTHING;
