INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skyriders', 'Inspired by classic games of the past, Skyriders is a fast-paced mix of platformer and racing game. Pilot a small spacecraft along crazy tracks in space, dodging and jumping obstacles, whilst trying to maintain a high speed by collecting the glowing stars and hitting the boost pads! Keep the boost streak going for massive scores and flawless runs - but you''ll need some well-timed switching between red and yellow to grab the matching stars! Can you master the increasingly challenging stages, get the gold medal scores, and climb those leaderboards?' FROM games WHERE igdb_id = 200099 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 200099 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
