INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Found a New Friend', 'You''ve had a long day. All you want to do is climb into bed. But why is your pillow quivering like that? I Found a New Friend is a short text adventure in the style of the old Infocom games. It is based loosely on the They Might Be Giants song of the same name.' FROM games WHERE igdb_id = 202568 ON CONFLICT (game_id, language_code) DO NOTHING;
