INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Go', 'TruckGo - Deliver goods to the marketplace with your truck. Collect coins to get advanced trucks, wheels and vip cards. You will need to get from one place to another without dropping too much from your truck. You will get a precise number of pieces you carry and a precise number of pieces that is required. The more you bring, the more score and coins you get.' FROM games WHERE igdb_id = 197670 ON CONFLICT (game_id, language_code) DO NOTHING;
