INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Crawlers', 'Dungeon Crawlers is a Turn-Based Strategy game. Take command of the Dungeon Crawlers team as they explore goblin-infested hallways, lava-drenched caverns, and other hostile environs in pursuit of loot, women, and monsters to crush.' FROM games WHERE igdb_id = 197806 ON CONFLICT (game_id, language_code) DO NOTHING;
