INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World At Arms', 'Enjoy the most beautiful war game on smartphone with outstanding graphics & animations! Engage in breathtaking battles across the globe and unleash deadly power-ups to crush your enemy! Immerse yourself in a long, rich and dynamic campaign with more than 75 missions to complete! Attack any player in the world, loot them for bonuses and climb up the leaderboards! Connect with your friends and borrow their units during battle to defeat tough enemies! Manage an extensive economy!' FROM games WHERE igdb_id = 106268 ON CONFLICT (game_id, language_code) DO NOTHING;
