INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brawl Busters', 'Brawl Busters is a class-based, free-to-play online action combat game. It features various cooperative and competitive modes for players to fight each other in arenas. The focus is entirely on multiplayer games against human opponents, but it also includes a singleplayer component where various tactics and moves can be trained against AI-controlled zombies in training sessions.' FROM games WHERE igdb_id = 20714 ON CONFLICT (game_id, language_code) DO NOTHING;
