INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Lords MMXII', 'Dungeon Lords MMXII is a remastered version of the original Dungeon Lords. Released following the cancellation of Dungeon Lords: The Orb and the Oracle, it offered the same story as the original and much of the same gameplay. In 2016, a revised version of the game was released on Steam.' FROM games WHERE igdb_id = 138038 ON CONFLICT (game_id, language_code) DO NOTHING;
