INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('imagine-fashion-life', 7950, '2012-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6cet.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imagine: Fashion Life', 'Imagine Fashion Life introduces a brand-new ultra-realistic fashion game on the Nintendo 3DS system where players can experience three fabulous fashion careers: fashion design, modeling and mall owner! The 3D game features high-quality, realistic graphics and allows players with a love of all things fashion to truly unleash their creativity and business savvy. Players can create original outfits and organize fashion shows as a fashion designer. As a top model, players can pose for glamorous photo shoots and set the catwalks ablaze with perfect runway walks. As a successful mall owner, players can open and arrange stores, decorate the mall, promote the trendiest cosmetics and fashion brands in stores, and manage their budget to create a world-class mall.' FROM games WHERE igdb_id = 7950 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 7950 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
