INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Very Pink Game', 'Play as Ivy, a lonely little girl living in a very pink town who has received a letter from her dear old friend. Ivy must find items and complete a series of tasks in order to see her again. Includes many ghosts, trees, a convenience store, a narcoleptic ghost hunter, and a punk who''s in love with a donut witch.' FROM games WHERE igdb_id = 151580 ON CONFLICT (game_id, language_code) DO NOTHING;
