INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max Payne Mobile', 'A fugitive undercover cop framed for murder, hunted by cops and the mob, Max is a man with his back against the wall, fighting a battle he cannot hope to win. Max Payne is a relentless story-driven game about a man on the edge, fighting to clear his name while struggling to uncover the truth about his slain family amongst a myriad of plot-twists. The groundbreaking original cinematic action-shooter, Max Payne introduced the concept of Bullet Time in videogames. Through its stylish slow-motion gunplay combined with a dark and twisted story, Max Payne redefined the action-shooter genre.' FROM games WHERE igdb_id = 86868 ON CONFLICT (game_id, language_code) DO NOTHING;
