INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('margrave-the-blacksmiths-daughter', 140989, '2012-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob134.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8r8t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Margrave: The Blacksmith''s Daughter', 'Embark on a thrilling rescue mission in Margrave: The Blacksmith''s Daughter! The town of the Cyclops appears for a single day once every three hundred years, on an island lost to cartographers. On this Day of Alignment, the town rises and sets with the midsummer sun. As the Margrave saga nears its devastating conclusion, Edwina Margrave embarks on a rescue mission into the town. Her only chance of escape is to return life to the arcane machines, and hope to the sole survivor of an ancient war, in Margrave: The Blacksmith’s Daughter. Prepare yourself for the adventure of a lifetime: the legacy of an entire civilization depends upon your cunning and compassion.' FROM games WHERE igdb_id = 140989 ON CONFLICT (game_id, language_code) DO NOTHING;
