INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splice: Tree of Life', 'Resequence, mutate, and splice in this experimental microbial puzzler by Cipher Prime. In this game you will plunge into the tiny world of molecules. You should expose molecules to make them create new life. In the game there’s magnificent graphics and an excellent gameplay, enjoy all beauty of life.' FROM games WHERE igdb_id = 91102 ON CONFLICT (game_id, language_code) DO NOTHING;
