INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pacific-fleet', 87506, '2012-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vnbua6zlatjsgohrmb2i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m3id4tzqefo9rnnfui1d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pacific Fleet', '"It really has too much detail and logic to be dismissed as an arcade game." - Neal Stevens, subsim.com "One of six games you should have played in 2013 (but probably didn''t)." - Owen Faraday, pockettactics.com Pacific Fleet is turn based game set upon a detailed simulation depicting naval warfare during World War II. Check out the full game trailer at: http://www.youtube.com/watch?v=8k7dq_0fPPc Features: - All new graphics depict the greatest war at sea in stunning full 3D - Historically based ships, aircraft, weapons and dozens of ship upgrades - A unique blend of deep strategic planning combined with quick tactical decisions - Play as the US Pacific Fleet or Imperial Japanese Navy - 90 combat zones to battle through on your way to victory - Single Battle and Multiplayer Hotseat modes - Complete 44 achievements - Sink ships with realistic buoyancy physics, not with hit-point bars! - Submarine warfare and carrier operations with dive bombing and torpedo bombers - Dynamic weather, shore bombardments and night engagements - Target specific ship subsystems to sink or cripple the enemy - 17 playable ships - 8 playable aircraft - Random ship placement, wind, weather and night engagements make each play-through unique - NO ADVERTISEMENTS. NO IN APPS. ONE PRICE = FULL GAME. Join us on Facebook for latest news and ongoing discussion with the developer: http://www.facebook.com/pages/Pacific-Fleet/313315455431274' FROM games WHERE igdb_id = 87506 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 87506 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
