INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi Blocksberg: Der verhexte Schloss-Schatz', 'Sensational exhibition in Klunkerburg Castle: The castle treasure is only shown to the public in the large throne room every ten years! Bibi''s school class is amazed. But then it happens: Bibi accidentally bewitches the treasure, which then spreads throughout the building. Fly, run and climb through the castle with Bibi and help her find the treasure!' FROM games WHERE igdb_id = 148498 ON CONFLICT (game_id, language_code) DO NOTHING;
