INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spaceteam', 'A cooperative shouting game for phones and tablets Do you like pushing buttons and shouting at your friends? Do you like discharging Clip-jawed Fluxtrunions? If you answered yes, or no, then you might have what it takes to be on a Spaceteam! Features: Teamwork An untimely demise Beveled Nanobuzzers Auxiliary Technoprobes Four-stroke Pluckers' FROM games WHERE igdb_id = 7207 ON CONFLICT (game_id, language_code) DO NOTHING;
