INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spell Dash', 'Spell Dash features 3 electrifying game modes that will keep you coming back for more. Arcade Mode: Find words quickly to clear the board before the letters reach the top. Timeless Mode: Play at your own relaxing pace. Be careful though, new letters will drop every time you find a word! Blitz Mode: Find words quickly before the clock runs out. Charge the frenzy meter to gain impressive bonuses and power-ups.' FROM games WHERE igdb_id = 174320 ON CONFLICT (game_id, language_code) DO NOTHING;
