INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Border Lands', 'The Border Lands is a 2D top-down browser version of the popular console game Borderlands 2. The game has cool 2D 16-bit graphics and authentic map locations to explore. Before starting, you can choose from 4 of the original characters from Borderlands 2 – Salvador, Maya, Zero or Axton - each character has unique abilities and differing skills.' FROM games WHERE igdb_id = 64696 ON CONFLICT (game_id, language_code) DO NOTHING;
