INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight Of The Earthends', 'Knight of the Earthends is a dynamic fantasy RPG set in a mysterious world unraveling at its edges. Follow Reiya, a courageous knight, as she journeys across wild lands with a golem companion and a mischievous unicorn girl, confronting ancient beasts and uncovering buried secrets. With turn-based battles, unique character growth systems, and 16-bit nostalgia, the adventure blends heartfelt storytelling with thrilling action.' FROM games WHERE igdb_id = 319835 ON CONFLICT (game_id, language_code) DO NOTHING;
