INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acrylic Palette: Irodori Cafe - Cheers', 'Acrylic Palette – Irodori Cafe – Cheers is a Visual Novel game developed and published by Klon Co., Ltd. for the Nintendo 3DS. It was released exclusively in Japan on December 20, 2012. A new sensation communication game that links reality and games. This work is a communication game set in a fictitious cafe. Real-life idols appear as characters in the game, and you can enjoy conversations and stories with them. Also, by earning points in mini-games, you can also collect gravures and movies that pop out with the stereoscopic function.' FROM games WHERE igdb_id = 222463 ON CONFLICT (game_id, language_code) DO NOTHING;
