INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unmanned', 'Now you get to play the newest kind of soldier: one who remotely drops bombs on foreign soil during the day, and at night goes home to his family in the suburbs. In Unmanned, the conflict is internal -- the only blood you''ll shed is from shaving cuts. But is there collateral damage in this new way of waging war?' FROM games WHERE igdb_id = 128744 ON CONFLICT (game_id, language_code) DO NOTHING;
