INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.O.T. Defender of Texel', 'In a world of squares, somebody needs to think outside the box… A high-fantasy adventure with a twist, "D.O.T." is set in Texel, an 8-bit retro universe in dire need of a champion. In this exciting new RPG from Mobage, the player is transported through a mobile game into a world that has no concept of death or war, and is being torn apart by sinister robotic invaders. Only your skills as a commander can save the three tribes of Texel, and open the portal back to your own reality.' FROM games WHERE igdb_id = 326505 ON CONFLICT (game_id, language_code) DO NOTHING;
