INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Dance', 'Wrap yourself up in the rich sound track: move your body to the rhythm and have fun with all the different choreographies available in the game. Let''s Dance is the only party game where you dance on the TV: it’s just like being on a talent show! Choose from a wide variety of dance styles: pop, club, ‘80s disco, Latin, urban, not forgetting the classic party tracks.' FROM games WHERE igdb_id = 78337 ON CONFLICT (game_id, language_code) DO NOTHING;
