INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Slayer Chronicle', 'Dragon Slayer Chronicle is a compilation of twelve games from the Dragon Slayer series released for the PC by D4 Enterprise on June 15, 2012 in Japan. The package includes reproductions of Xanadu''s and Dragon Slayer''s original manuals, various artwork from the franchise and a soundtrack disc. Titles contained in the release include: - Dragon Slayer - Xanadu: Dragon Slayer II - Xanadu Scenario II - Romancia - Dragon Slayer IV: Drasle Family - Sorcerian - Dragon Slayer: The Legend of Heroes - Dragon Slayer: The Legend of Heroes II - Lord Monarch - Advanced Lord Monarch - The Legend of Xanadu - The Legend of Xanadu II' FROM games WHERE igdb_id = 112155 ON CONFLICT (game_id, language_code) DO NOTHING;
