INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gnosis', 'Doug Bigham liven an enjoyable life as a member of a safety riot team, until he found himself lying in the middle of the debris of a town with no memory and serious injuries. His dream world and memories are his only method to rebuild the events that brought him to that situation. Collect the regular 19 effects and also Gag Effects to unlock the endings.' FROM games WHERE igdb_id = 201292 ON CONFLICT (game_id, language_code) DO NOTHING;
