INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild West Races', 'Wild West Races is an adaptation of popular racing card game Mille Bournes. Each player manipulates a cowboy who is riding at a full speed over the prairies in a ruthless survival race. You can help him by playing a distance or a bonus card. You can also hinder the way of your opponent by playing a card which will prevent him from moving any further.' FROM games WHERE igdb_id = 175395 ON CONFLICT (game_id, language_code) DO NOTHING;
