INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oh Mummy Genesis', 'Oh Mummy Genesis is an unlicensed Sega Mega Drive game developed and published by 1985 Alternativo. It was released in October 2012 and serves as an unofficial update to the game Oh Mummy, originally released by Gem Software for the Amstrad CPC, MSX and ZX Spectrum in 1984. As well as providing a port of the original version, Oh Mummy Genesis features an updated version with enhanced graphics and sound.  1985 Alternativo released the ROM as freeware in 2013, after stocks of boxed copies of the game ran out.' FROM games WHERE igdb_id = 46160 ON CONFLICT (game_id, language_code) DO NOTHING;
