INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baseball Superstars 2013', 'The Ultimate Smart Baseball Experience Returns The anticipated Baseball Superstars series is back better than ever! Featured in crisp, clear HD- this is the best baseball game for mobile devices. With enhanced batting and pitching moves, players experience smart intuitive baseball as never before. New and improved My Pitcher and My Batter modes lets you experience best of both worlds as you train, challenge, and compete for first place. Grow from rookie to super star by tackling new quests and relationships with your fans and cohorts! Join the millions of fans world wide in this epic baseball RPG experience!' FROM games WHERE igdb_id = 38708 ON CONFLICT (game_id, language_code) DO NOTHING;
