INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who''s Gonna Get the Girl?', 'In this comedy role playing game you play the part of a young love starved man whose hopes are sparked to life by meeting a beautiful girl! Will you make it up to her apartment? Will you get to see her excusive lingerie fashion show? Will you find Love? Loads of randomly set variables so as game is different every time you play!' FROM games WHERE igdb_id = 271966 ON CONFLICT (game_id, language_code) DO NOTHING;
