INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouncy Ball', 'Navigate a ball to collect stars while avoiding various obstacles and traps. With over 800 levels spread across more than 20 worlds, the game features a unique map editor and an online map store, allowing players to create and share their own levels. Bouncy Ball is a mobile game that has captivated over 10 million users worldwide, ranking as the second overall free app and the second top brain and puzzle game in South Korea.' FROM games WHERE igdb_id = 245201 ON CONFLICT (game_id, language_code) DO NOTHING;
