INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ragnarok-odyssey-mercenary-edition', 42705, '2012-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9h4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mtgrpwahg63su6ntws7w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ragnarok Odyssey: Mercenary Edition', 'Ragnarok Odyssey is an Action Role-Playing game (RPG) for PlayStation Vita, that is set in a unique environment based in Norse mythology. Loosely built upon the world of the South Korean MMORPG Ragnarok Online, Ragnarok Odyssey challenges players to protect their home of Rune Midgard from a rampaging mass of invading giants, set on destruction. To do so they will have to master a challenging battle system full of fluid combos and chain attacks, and enlist the help of friends online. Additional features include: deep character customization, six job classes, and beautiful cutscenes that take advantage of the PS Vita''s superior graphics capabilities. Mercenary Edition Items Included: - Ragnarok Odyssey - CD game soundtrack - The "Guild of Midgard Mercenary Guide" containing art and strategy tips - A pack of 10 monster cards' FROM games WHERE igdb_id = 42705 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42705 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
