INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flying-hamster-hd', 52220, '2012-12-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60qq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flying Hamster HD', 'Flying Hamster HD is a high-definition version of Flying Hamster game previous released as PlayStation minis release for earlier PlayStation platforms as well as for PS Vita. The game itself is the same, featuring 6 levels in total, following the story of Newton, the flying hamster whose girlfriend got kidnapped by a giant eagle, as he is fighting his way through waves of other animals, robots and aliens trying to save his beloved. The game is presented as a horizontally scrolling shooter much like Apidya where you can use single or auto-fire and collect other weapons and upgrades by destroying your enemies.' FROM games WHERE igdb_id = 52220 ON CONFLICT (game_id, language_code) DO NOTHING;
