INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brandnew Boy', 'Brandnew Boy is a 3D action game where the protagonist, known only as "Rookie," wakes up in an unfamiliar world with no memory of who he is or how he got there. Surrounded by hostile enemies and accompanied by a mysterious robot with a TV for a head, Rookie must fight to survive while uncovering the truth about his past.' FROM games WHERE igdb_id = 38975 ON CONFLICT (game_id, language_code) DO NOTHING;
