INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless, Nameless', 'You are a yet another brave adventurer set upon the quest to slay the mighty dragon that is threatening the village! Following the questing traditon, you decide to start your search for the dragon in the local tavern! What makes this quest different? It takes place on the worldz best BBS! hehehe!!!  A piece of interactive fiction by Adam Cadre.' FROM games WHERE igdb_id = 60116 ON CONFLICT (game_id, language_code) DO NOTHING;
