INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '94 Seconds: category word game', '* Play with your friends or randomly against one of the 12 million players 1 category, 1 letter, 1 word to find and score higher than your friends. A fruit with B? A sport with T? A mammal with D? Want to play? Then download fast 94 Seconds categories game right now! More than 50 different categories: countries, fruits, US cities, musical instruments, tools, cosmetics...' FROM games WHERE igdb_id = 27788 ON CONFLICT (game_id, language_code) DO NOTHING;
