INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stick War 2', 'Stick War 2: Order Empire is a real-time strategy game where players command armies to reunite rebellious factions in the land of Inamorta. Players manage resources through mining and prayer mechanics while controlling units tactically using mouse and keyboard commands. The game challenges players to face the Magikill-led rebels and an emerging evil threat.' FROM games WHERE igdb_id = 234291 ON CONFLICT (game_id, language_code) DO NOTHING;
