INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the World: Tactics Union', 'Revalia is a world formed from the dreams of people from countless different worlds. As long as there are those who dream, it continues to exist; when they cease to dream, the world will die. Within Revalia resides the Rufres tribe, whose duty is to keep the balance in the world by purifying the nightmares of the people, the incarnation of the people''s darkness in their hearts called Vuul.' FROM games WHERE igdb_id = 294585 ON CONFLICT (game_id, language_code) DO NOTHING;
