INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Trains', 'Race the fastest trains and prove that you''re the best racer! Compete with crazy train racing gangs and avenge your family! Drive the trains equipped with huge jet engines and experience supersonic speed! Ready, Set, Go! Race your supersonic Jet Trains through numerous missions, face off against challenging bosses, create your train the way you want, unlock different levels, and execute outrageous stunts and jumps in order to be the first across the finish line!' FROM games WHERE igdb_id = 174200 ON CONFLICT (game_id, language_code) DO NOTHING;
