INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fox & Hounds', '"Fox and Hounds" is an exciting strategy game for every age! It is played on an 8x8 chess/checkers board. The four hounds try to trap the fox while the fox attempts to reach the other side. The difficulty levels range from easy to challenging. This strategy game is also called "Wolf and Sheep", "Hounds and Hare" or "Devil and Tailors". Easy to play, hard to put down!' FROM games WHERE igdb_id = 175108 ON CONFLICT (game_id, language_code) DO NOTHING;
