INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forbidden Secrets: Alien Town Collector''s Edition', 'Step bravely into the unknown with Forbidden Secrets - Alien Town, an uneasy investigation into uncharted territory. A TV show is turning the children of Fort Nightingale into strange beings and adults into motionless living dolls. As the government agent in charge of investigating unexplained phenomena, Clarissa undertakes her most perplexing case yet.' FROM games WHERE igdb_id = 53035 ON CONFLICT (game_id, language_code) DO NOTHING;
