INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast Soccer', 'Blast Soccer combines intense arcade gameplay, gorgeous retro style, soccer and explosions. Score goals as fast as you can while blowing up your enemies! Avoid the ever increasing volley of bad guys as you score with soccer balls, footballs, basketballs, and Blast Balls. Complete missions to unlock new ball types such as the disco ball, mega ducky, and the cube. Blast Soccer''s unique retro vector art style will take you back to the arcade’s golden days.' FROM games WHERE igdb_id = 174376 ON CONFLICT (game_id, language_code) DO NOTHING;
