INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astronaut Spacewalk', 'Astronaut Spacewalk is a highly realistic astronaut jetpack simulator. Fly the Manned Manouvering Unit from the Space Shuttle cargo bay to several satellites, align into position to make repairs and dock back into the Shuttle. Fly the jetpack in 20 daring missions where you have to rendezvous with different satellites from the smaller TDRS and Solar Maximum, medium sized like the Magellan and Galileo probes, to the big Skylab, Hubble telescope and Russian MIR station.' FROM games WHERE igdb_id = 174354 ON CONFLICT (game_id, language_code) DO NOTHING;
