INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hill-climb-racing', 38680, '2012-09-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69yv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bqndwt4ldb3por7isar8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hill Climb Racing', 'One of the most addictive and entertaining physics based driving games ever made! And it''s free! Meet Newton Bill, the young aspiring uphill racer. He is about to embark on a journey that takes him to where no ride has ever been before. From Ragnarok to a Nuclear Plant, all places are a racing track to Bill. With little respect to the laws of physics, Bill will not rest until he has conquered the highest hills up on the moon! Face the challenges of unique hill climbing environments with many different cars. Gain bonuses from daring tricks and collect coins to upgrade your car and reach even higher distances. Watch out though - Bill''s stout neck is not what it used to be when he was a kid! And his good old gasoline crematorium will easily run out of fuel. Features: - Lots of different vehicles with unique upgrades (many different vehicles: bike, truck, jeep, tank, etc.) - Tuneable parts include engine, suspension, tires and 4WD - Numerous stages with levels to reach in each (Countryside, Desert, Arctic and the Moon! +++) - Share your score with a screenshot with your friends! - Cool graphics and smooth physics simulation - Designed to look good on low resolution and high resolution devices (incl. tablets) - Real turbo sound when you upgrade your engine! - Garage mode: build and drive your dream vehicle with custom parts! - Get new boosters to drive even further - 27+ Levels! - 28+ Vehicles!' FROM games WHERE igdb_id = 38680 ON CONFLICT (game_id, language_code) DO NOTHING;
