INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Quest: Incinerations', 'Space Quest: Incineration is a 2012 fan-made sequel to the Space Quest series, created by Chris Ushko. It had been previously started in 1999 as a team project, cancelled, and then revived again as an almost completely different game. Information for both versions of the game are kept on this page.' FROM games WHERE igdb_id = 265067 ON CONFLICT (game_id, language_code) DO NOTHING;
