INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Balloon Heads 2', 'Fiends, zombies and enemies of a stickly kind are here to ruin your day. No chance! Blast their hollow heads until they fill up with ink, and watch their skulls explode. Delightful! Travel through history and time, meeting and destroying lotsa zombies. Inky hilarity ensues! Second installment in the Zombie Balloon Heads series.' FROM games WHERE igdb_id = 234141 ON CONFLICT (game_id, language_code) DO NOTHING;
