INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Durak', 'In Soviet Russia cards play you! Durak is a famous Russian card game. The goal of the game is to get rid of your cards before your opponents. There''s an element of luck, a good bit of strategy and a ton of fun to be had. Play against the computer or your friends, online, via Bluetooth, or on the same device by passing it back and forth in the Pass & Play mode.' FROM games WHERE igdb_id = 174336 ON CONFLICT (game_id, language_code) DO NOTHING;
