INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: Book of Memories', 'Silent Hill: Book of Memories is a Silent Hill role-playing spin-off game exclusively for the PlayStation Vita. The primary focus of the gameplay is on dungeon-crawling and cooperative multiplayer action, rather than the survival horror elements that the series is known for. Players can work together as they explore several different Otherworlds, solving puzzles and defeating creatures to advance through the Nightmares and uncover the truth behind the Book of Memories. Scare rooms, limited resources, and dark atmosphere all return but in a gameplay package specifically designed to take advantage of the PlayStation Vita handheld entertainment system.' FROM games WHERE igdb_id = 9714 ON CONFLICT (game_id, language_code) DO NOTHING;
