INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hypersonic 4', 'HyperSonic 4 is a high speed action shooting game. This is a jet game with loads of missiles, explosion and action. The player will take role of fighter jet pilot in intense story driven campaign. This game will pump your adrenaline up. HyperSonic feature both SinglePlayer campaign and teamed Multiplayer battle.' FROM games WHERE igdb_id = 10424 ON CONFLICT (game_id, language_code) DO NOTHING;
