INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BounceBash', 'Grab small stars with the paddle for big bonuses! Snag big stars for awesome new powers that will help Dillo Bash even more! New worlds are revealed as you gain new powers - explore them all! Play to unlock new abilities, then mix and match any four to find your winning combination--over 11,000 combinations of power-ups to choose from!' FROM games WHERE igdb_id = 248059 ON CONFLICT (game_id, language_code) DO NOTHING;
