INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PathPix Joy', 'Sunrise to sunset and on into the night, PathPix Joy will keep you smiling with 99 puzzles, easy to extreme. Draw bright, bold lines of color to make paths connecting pairs of colored numbers. The length of each path must equal the numbers you are connecting. Finish solving to see the miniature picture that you have created. As an extra reward you get a quote related in some way to the picture. Witty or wise, it will give you a little something to think about as you go on to the next puzzle.' FROM games WHERE igdb_id = 106880 ON CONFLICT (game_id, language_code) DO NOTHING;
