INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fowl Space', 'A heroic rooster sets forth on a ridiculous space adventure to DESTROY THE SUN! Unfortunately for him, a legion of lingerie-loving Vikings has turned it into their headquarters and they’re big fans of fried chicken. Full of high tech weaponry, constant non sequitur, terrible gaming humor and a wanton disregard for anything wholesome; Fowl Space is a crazy journey you’ll never forget... to say the least.' FROM games WHERE igdb_id = 15144 ON CONFLICT (game_id, language_code) DO NOTHING;
