INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ys-memories-of-celceta', 15457, '2012-09-27', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1l5r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pped5zlbkwecbfc4rn58.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys: Memories of Celceta', 'A bustling town deep in the frontier at the foot of an endless sea of trees... It is into this wild and untamed setting that a young man collapses, memories gone and only his name to guide him. Bereft of his past, Adol Cristin wanders the town of Casnan searching for clues to his identity. Joined by an information dealer who claims to have known him, the young adventurer helps rescue doomed miners from a collapse; an act which attracts the attention of the Romun Army general in town. Impressed with their skills, the pair is enlisted to explore the Great Forest and map the vast expanses of Celceta – a task which many have attempted in the past, but from which none have ever returned alive. Alone in this strange and uncharted frontier, Adol must brave the perilous sea of trees as he struggles to regain his memories and decide whom he can trust, and who is simply attempting to take advantage of his memory loss in order to deceive him...' FROM games WHERE igdb_id = 15457 ON CONFLICT (game_id, language_code) DO NOTHING;
