INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Soul', 'Rogue Soul is an endless running platformer game developed by SoulGame Studio. It has you take control of the titular character, Rogue Soul, as he runs through the city looking to raise the bounty on his head to 5,000 Soulons in order to become more famous than Borin Hood, the current most famous criminal in the city.' FROM games WHERE igdb_id = 300603 ON CONFLICT (game_id, language_code) DO NOTHING;
