INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty: Picnic with Sanrio Friends', 'Hello Kitty Picnic with Sanrio Friends invites players to join Hello Kitty and Sanrio friends as they prepare for a picnic adventure. Play 10 mini-games including Hidden Object, Spot the Difference, and Picnic Blanket Checkers to collect goodies for the party. Explore and decorate whimsical environments including Hello Kitty''s bedroom, kitchen and more. Along the way earn apples to receive special outfits and accessories for Hello Kitty. Interact directly with Hello Kitty using the 3DS touch screen and listen as the game guides you along. Invite your friends to join the fun in a variety of multiplayer modes as you play with your favorite Sanrio characters including My Melody, Keroppi, Chococat, Badtz-Maru, Little Twin Stars, and many more!' FROM games WHERE igdb_id = 7437 ON CONFLICT (game_id, language_code) DO NOTHING;
