INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Road', 'Endless Road is a top-down racer where you steer your car around the trials and tribulations of a three-lane highway. As one portion of the road ahead unfolds to lengthen your journey, so an equal portion of the road behind you falls into ruin. Should you fail to keep your speed up, and slip behind the line that marks the approaching cataclysm, then your high-score attempt will end and it''s back to the drawing board.' FROM games WHERE igdb_id = 112438 ON CONFLICT (game_id, language_code) DO NOTHING;
