INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Maiden Wars: Mystic', 'The second game in the Gensou Shoujo Taisen series after Kou, the overarching story is based on the plots of Mountain of Faith (A.K.A Touhou 10), Immaterial and Missing Power ( Touhou 7.5) and Perfect Cherry Blossom (Touhou 7) in that order. Player can transfer save data from the previous game allowing player to retain items, upgrades, and database information as well as gain some bonuses.' FROM games WHERE igdb_id = 144060 ON CONFLICT (game_id, language_code) DO NOTHING;
