INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Royal Trouble: Hidden Adventures', 'Princess Loreen and Prince Nathaniel have been kidnapped, and need your help to escape from a mysterious dungeon! Control both characters and manage both of their inventories in Royal Trouble, a fast-paced Hidden Object Puzzle Adventure game! Navigate treacherous locations, and escape from the kidnappers before it is too late! Teach Loreen and Nathaniel to work together in order to solve puzzles and reach safety.' FROM games WHERE igdb_id = 87899 ON CONFLICT (game_id, language_code) DO NOTHING;
