INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terapets', 'Teraland is a fantastic world where humans live together with some creatures called Terapets. They have always lived happily in harmony with nature and the inhabitants of Teraland. But, for some reason, not long ago, the Terapets have lost their melody and, therefore, their light and happiness... What''s the reason for this tragedy? They need somebody whose bravery and spirit will make possible the return of the melody to the Terapets. Could it be you?' FROM games WHERE igdb_id = 135448 ON CONFLICT (game_id, language_code) DO NOTHING;
