INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sports-champions-2', 18238, '2012-10-30', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a62.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lhorxnqqdkemh9zmntjp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Champions 2', 'Using the PlayStation Move motion controller and PlayStation Eye, players become part of the event as they use their controllers to compete in a variety of new sporting challenges. Building upon the game mechanics of the first title, Zindagi Games and Sony’s Worldwide San Diego Studio make it easily accessible for players of all levels to jump right into the action. Each of the six events will have you energized as you improve your backswing, bowl a strike or perfect your left hook. Sports Champions 2 comes with six pulse-pounding events including five new games and an update to the beloved Archery event from the first title. The new events include Skiing, Tennis, Boxing, Golf, and Bowling, offering a variety of activities that will appeal to everyone. Sports Champions 2 features new game modes, including Party Play, a new game feature, which invites you to compete with your family and friends in custom, multi-sport tournaments. It will also include beginner friendly controls without needing to calibrate for easier pick-up-and-play, ensuring competitors of all ages can jump right in and join the fun, while seasoned veterans can choose advanced modes for a greater challenge. For added fun, users can choose the new Create-a-Player function to customize everything from their character’s outfit to their animation and sound. As you play, unlock new clothing, equipment and accessories to keep the creativity flowing.' FROM games WHERE igdb_id = 18238 ON CONFLICT (game_id, language_code) DO NOTHING;
