INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess Plus+', 'Chess Plus+ is an enhanced computer chess game powered by a sophisticated artificial intelligence engine resulting in automated opponent player ratings ranging from Novice to Grandmaster! With Chess Plus+ you will engage in challenging computer player chess games whether you''re just starting out or an old pro. Algorithmically varied computer opponent gameplay simulates real-world match conditions. The game includes 4 chess ebooks built-in for offline reading on chess fundamentals, strategy, gameplay, and openings.' FROM games WHERE igdb_id = 86901 ON CONFLICT (game_id, language_code) DO NOTHING;
