INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Six-Guns: Gang Showdown', 'Explore a truly enormous and open Wild West frontier full of cowboys, bandits and more…unnatural enemies in this third person shooter adventure game. Buck Crosshaw never shot a man who didn’t deserve it, but now he’s an outlaw who had to fake his own death and escape to Arizona. But in escaping one evil, Buck is about to face another, for an ancient and wicked force stirs in the hills of this mysterious region.' FROM games WHERE igdb_id = 38991 ON CONFLICT (game_id, language_code) DO NOTHING;
