INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Royal Detective: Lord of Statues', 'The player interface and game mechanics provide traditional graphical adventure with on screen movement touch points, puzzles and hidden-object search style game play. Objects collected in inventory at the bottom of the screen require the player to drop or drag them onto other items in the scenes to activate or complete needed tasks. During the adventure you will also acquire friendly statues as tag along pets (rooster, gnomes, etc) that help aid in key actions needed to achieve puzzle solutions. An interactive map allows for quick travel to various locations previously explored to reduce scene movement and backtracking.' FROM games WHERE igdb_id = 57968 ON CONFLICT (game_id, language_code) DO NOTHING;
