INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asphalt 7: Heat', 'The seventh series of Asphalt franchise. Hit the speed of heat in the newest, fastest, most visually stunning edition of the famed Asphalt series. Drive 60 different cars from the world’s most prestigious manufacturers, like Ferrari, Lamborghini and Aston Martin, including the legendary DeLorean and gear up to race on 15 tracks set in real cities around the world, including brand new tracks in Hawaii, Paris, London, Miami and Rio.' FROM games WHERE igdb_id = 23305 ON CONFLICT (game_id, language_code) DO NOTHING;
