INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hack Time', 'Once again, your mission is to penetrate a strange organization’s infrastructure to discover their secrets. Your employer needs help discovering who is out to get her and she only trusts you to take on this perilous mission. Hack Time uses old-school prompts (like DOS and UNIX) to access virtual programs and systems. Gain access to users’ files and emails to discover new ways to dig deeper and deeper.' FROM games WHERE igdb_id = 51450 ON CONFLICT (game_id, language_code) DO NOTHING;
