INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apple Avengers', 'Apple Avengers is an action/adventure/platformer similar to Super Mario Bros. You play the role of Fuji, a heroic apple who embarks on a quest through 5 bright and colourful worlds overrun by an army of worms. You will earn 8 different Powerups throughout the game allowing you to transform into one of the legendary Apple Avengers. Use their skills to fight, jump, fly and roll your way through 55 levels of platforming madness and 4 unique automatic running levels.' FROM games WHERE igdb_id = 106871 ON CONFLICT (game_id, language_code) DO NOTHING;
