INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qasir Al-Wasat: A Night in-Between', 'Qasir Al-Wasat: A Night in-Between tells the story of an invisible and frail creature which is summoned on 12th century Syria for a mission of infiltration and assassination, where it investigates and discovers the secrets of a wondrous palace and a trap that was set for it. The game employs simple mechanics and conceptual sounds and visuals.' FROM games WHERE igdb_id = 64290 ON CONFLICT (game_id, language_code) DO NOTHING;
