INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue: Continuum Shift Extend - Limited Edition', 'BlazBlue: Continuum Shift is a 2009 fighting game developed by Arc System Works as an official sequel to BlazBlue: Calamity Trigger. As with the previous game, the game first came to arcades before both the Xbox 360 and PlayStation 3 versions as the game was currently released for the Taito Type X2 arcade system board, with a 16:9 ratio and 768p resolution. Revisions entitled BlazBlue: Continuum Shift II and BlazBlue: Continuum Shift Extend were released in arcades in 2010-2011. They were later ported to the PlayStation 3, PlayStation Portable, Nintendo 3DS, and Windows.' FROM games WHERE igdb_id = 43025 ON CONFLICT (game_id, language_code) DO NOTHING;
