INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wicked Rider', 'Wicked rider is a retro motorcycle racing game, with a similar style to ''outrun'', ''lotus'' and ''crazy cars'' series in Amiga/DOS. There are 15 tracks, betting rivals and upgrades. Well, that''s pretty much it.' FROM games WHERE igdb_id = 187129 ON CONFLICT (game_id, language_code) DO NOTHING;
