INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Win Football', 'From the opening kickoff to the game winning touchdown, Big Win Football is the gridiron game for everyone! Create your own unique dream team, compete against opponents from around the world, watch your team battle it out on the field, boost your player''s throwing, tackling, running and other skills and get ready to hoist the Daily Bowl for the ultimate big win!' FROM games WHERE igdb_id = 59616 ON CONFLICT (game_id, language_code) DO NOTHING;
