INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disney-city-girl', 62415, '2012-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w3f.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney City Girl', 'With suitcase in hand, it''s time to leave your small-town life behind and head to the big city to make your dreams come true! Do you have what it takes to skyrocket to stardom? In the spirit of Sorority Life, players will engage in a stylish and aspirational virtual world, working their way through careers paths, apartment upgrades, daily catwalks, and fashion galore. From a grungy studio to a Park Avenue penthouse, from overworked intern to successful CEO, from country bumpkin to glamour girl, City Girl will keep players coming back again and again!' FROM games WHERE igdb_id = 62415 ON CONFLICT (game_id, language_code) DO NOTHING;
