INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder She Wrote 2: Return to Cabot Cove', 'Acclaimed mystery author Jessica Fletcher seems to find herself stumbling across more than her share of murder scenes, but her keen eye for detail, quick wits, and intuition make it even unluckier for the murderers! Based on the classic TV show of the same name, "Murder, She Wrote 2: Return to Cabot Cove" lets you work side by side with Jessica while solving three all-new cases in this gorgeous light adventure/hidden object game. Navigate through the lovely but lethal New England village of Cabot Cove to solve clever puzzles and ultimately discover whodunnit!' FROM games WHERE igdb_id = 10574 ON CONFLICT (game_id, language_code) DO NOTHING;
