INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earn to Die HD', 'With only a run-down car and a small amount of cash at your disposal, your mission soon becomes clear – to drive through hordes of zombies in order to escape... alive! Earn to Die sees you not only driving your way through hordes of zombies, but allows you to earn cash to upgrade, unlock and customise new vehicles. Is your vehicle not strong enough? Why not add a gun, or boosters, or even a spiked frame?' FROM games WHERE igdb_id = 86888 ON CONFLICT (game_id, language_code) DO NOTHING;
