INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Topia World Builder', 'Topia World Builder is a world creation simulation. You become god and shape the land as you choose, by the use of touch controls. Swipe your finger to create mountains, valleys, rivers, and oceans. Watch trees grow, spawn thousands of animals - and watch them live and die on the planet of your creation!' FROM games WHERE igdb_id = 87876 ON CONFLICT (game_id, language_code) DO NOTHING;
