INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nikoli no Puzzle V: Numberlink', 'Nikoli''s "Numberlink", which is famous all over the world, is now available on PlayStation®Vita! All 50 questions recorded are handmade by Nikoli''s puzzle writer, so the feeling of solving is different! In addition, the operation unique to PlayStation®Vita makes it easier to play with problems with large board sizes! From beginners to advanced players, please enjoy the deep world of puzzles. * "Numberlink" is a registered trademark of Nikoli Corporation.' FROM games WHERE igdb_id = 178757 ON CONFLICT (game_id, language_code) DO NOTHING;
