INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cangaco-wargame', 285218, '2012-06-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7psj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqe4r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cangaço Wargame', 'Originally conceived as a board game, the developers realized during the development process that it was gaining many elements that are closely related to the dynamics of social games. That''s precisely why the game was developed for Facebook. In this multiplayer-focused game, you must lead a group of cangaceiros (bandits) in turn-based battles, navigating through farms, towns, and swamps of the caatinga (Brazilian northeastern region). The battles occur turn by turn, and a single combat can last from a few minutes to several weeks: you make your move and then wait for your opponent (who might be offline at the moment). There are two distinct groups in the game: the cangaceiros and the volante (police force). As you challenge and defeat your enemies, you climb the ranks, getting closer to the title of the cangaço king.' FROM games WHERE igdb_id = 285218 ON CONFLICT (game_id, language_code) DO NOTHING;
