INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Dance Kinect', 'America''s hottest country music stars are headed to your living room for a brand new interactive dance experience with bonus sing-a-long features that''s packed with dozens of hits from your favorite country chart-toppers! Country Dance All Stars features more than 35 tracks from the best names in country music including 18 CMA 2011 award winners like Male and Female Vocalists of the Year Blake Shelton and Miranda Lambert, Album of the Year winner Jason Aldean and Vocal Duo of the Year Lady Antebellum. Songs from mega stars Brad Paisley, Carrie Underwood, Zac Brown Band, Brooks&Dunn and Eric Church will also headline the dance party. See below for a partial list of the in-game soundtrack revealed today.' FROM games WHERE igdb_id = 41591 ON CONFLICT (game_id, language_code) DO NOTHING;
