INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil''s Attorney', 'Devil''s Attorney is a turn-based strategy game set in the 80''s where you play as Max McMann, a defense attorney that''s high on charm but low on moral fiber. Your objective is to free all of your clients and use the money you earn to buy accessories and new furniture for your apartment; boosting your ego and unlocking new courtroom skills in the process.' FROM games WHERE igdb_id = 27090 ON CONFLICT (game_id, language_code) DO NOTHING;
