INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Star Soccer', 'Welcome to New Star Soccer. The soccer game acclaimed and adored by players and the gaming press en masse. Build your skills, lifestyle and ride the roller-coaster of life as you experience every emotion this great sport has to offer! Manage your relationships, keeping team-mates, the coach, your partner and your sponsors happy as you face dilemmas and exciting twists along the way. Risk your earnings in the casino, explore sinister bribes and eventually retire to set a new career game score!' FROM games WHERE igdb_id = 7674 ON CONFLICT (game_id, language_code) DO NOTHING;
