INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyakki Yakou: Kaidan Romance', 'Hyakki Yakou: Kaidan Romance was released in 2012. It is the second game in the Kaidan Romance series. The Kaidan Romance games are split into three sets of games set in the same world but with different characters and protagonists. This is the first game in the Tatsuta Ui line, with the sequel being Hyaku Monogatari ~Kaidan Romance~.' FROM games WHERE igdb_id = 219136 ON CONFLICT (game_id, language_code) DO NOTHING;
