INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kobayashi-maru-final', 301772, '2012-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co887q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs9n3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kobayashi Maru: Final', 'An Atari Jaguar CD homebrew game that is heavily inspired by Konami''s arcade game Time Pilot. Kobayashi Maru is a 50/60 fps rotary action shooter for the Atari Jaguar games console and was written utilising a version of RAPTOR API by Reboot. It can be played with either a rotary controller (such as Chaos Reins, Tyrant or Jonathan Ascough pad) or a regular Jaguar joypad. Xu’s United Nations Tetrad are under simultaneous attack from The Ebil Alliance. All that stands between TEA and the XUNTS is you and your warpships. You are the only officer capable of piloting these ships and are therefore the last hope of all XUNT-kind. As your prototype warpships do not come fitted with stabilising or reverse thrusters, your ship tears around the upper atmosphere with regular engines at full output. Your task is to steer the warpship, avoid collisions and kill the attacking drones. Once the required number of drones have been dispatched, their mothership will arrive and attempt to seek revenge. Defeat this mothership and you’ll charge your warp engines and be off to the next planet where you’ll find new drones are on the attack. Some drones have taken your fellow XUNTs hostage – you are able to rescue these falling hostages by catching them with your ship, but beware – if you destroy their baloonachutes they’ll fall much more quickly. Chain hostage rescues for increased bonuses, lose a warpship and the chain will reset. As you defeat drones, your allies below collect their wreckage, recycle it and construct further warpships for your use. 1st extra warpship at 20,000 and every 50,000 afterwards. Lose a warpship and your allies will transport a new one to your position. TEA wins when you no longer have any warpships to replace your damaged vessel.' FROM games WHERE igdb_id = 301772 ON CONFLICT (game_id, language_code) DO NOTHING;
