INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Ninjas Adventures', 'Calling all ninjas! Get ready to swipe, kick and battle your way through 21 levels of intense ninja action as you help Hiro rescue his master and fellow ninjas from the clutches of the evil Samurai Warlord. Be prepared to face a multitude of enemies that will push your skills to the limit and test your ingenuity. So pack your ninja stars, sword and more and get ready for adventure...a Mini Ninjas Adventure.' FROM games WHERE igdb_id = 20234 ON CONFLICT (game_id, language_code) DO NOTHING;
