INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mib-alien-crisis', 5005, '2012-05-22', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjgdz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MIB: Alien Crisis', 'Become the next top agent of the Men In Black. Arm yourself with a full arsenal of iconic MIB weapons to investigate and stop an evil alien plot to snatch up an ancient artifact that is the key to seizing control of the universe. It’s your turn to suit up as the newest MIB recruit to eliminate the scum of the universe. Arm yourself with a full arsenal of iconic MIB weapons and head into the field with the mission to investigate and stop an evil alien plot to snatch up an ancient artifact that is the key to seizing control of the universe. Features • 3rd Person Combat Tactics: Dodge and take cover as you battle hostile aliens in this action-packed, 3rd person rail shooter. • Nothing is What it Seems: Aliens often use clever disguises. Employ MIB investigative techniques to detect hidden threats. • Diverse and Customizable Weapons: Wield a full arsenal of official MIB weaponry from the Noisy Cricket to the Deatomizer and even select from a full array of awesome firepower modes such as “Freeze Ray” and “Anti-Gravity Grenade.” • High Octane Action-Oriented Experience: Pursue and escape fierce aliens in intense cinematic chase sequences. • Multi-Player Battles: Challenge your friends and family to competitive split screen 2-player or up to 4-player “hot-seat” action! • Top Shot Elite Compatible: Take fighting alien scum to the next level with the Top Shot Elite peripheral.' FROM games WHERE igdb_id = 5005 ON CONFLICT (game_id, language_code) DO NOTHING;
