INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinect Nat Geo TV', 'A ground-breaking interactive experience developed as part of Microsoft \"playful learning\" initiative, Kinect Nat Geo TV uses Kinect to combine motion-control with augmented reality. It mixes high-quality National Geographic television shows with fun-packed Xbox 360 Kinect motion-controlled game play.With Kinect Nat Geo TV, you\''re not only gaming and you\''re not only watching TV -- living rooms are turned into animal habitats and players into a variety of animals! And all along, players are inspired to learn and care about the planet. Kinect Nat Geo goes beyond what a TV show can do: it is a totally immersive experience for parents and kids.' FROM games WHERE igdb_id = 22343 ON CONFLICT (game_id, language_code) DO NOTHING;
