INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon City', 'Build yourself a magical city and fill it with buildings, habitats, and dragons! Feed your dragons and make them evolve into strong beasts! You''ll be able to train them and teach them new skills. Collect over 600 dragons of different elements and rarities to complete the Dragon Book. You can become the top collector in the game! Battle against other players in the Dragon Leagues and face exciting challenges in the tournaments to win lots of rewards!' FROM games WHERE igdb_id = 38877 ON CONFLICT (game_id, language_code) DO NOTHING;
