INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hakuoki-demon-of-the-fleeting-blossom-limited-edition', 42714, '2012-03-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7236.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakuoki: Demon of the Fleeting Blossom - Limited Edition', 'Hakuoki: Demon of the Fleeting Blossom is a visual novel that follows the story of a young woman by the name of Chizuru who is searching for her missing father. Set around the end of Edo period when samurai warriors are becoming a remnants of a past era. While not being a downright love simulation, the game lets you pursue a relationship with some of the male characters. As such, the game was released on Valentine''s Day and is focused more towards the female audience. As many games of its genre, it also features multiple endings based on choices you make throughout the story. This limited edition contains: Hakuoki: Demon of the Fleeting Blossom (with different cover art) 72-page full-color artbook Soundtrack' FROM games WHERE igdb_id = 42714 ON CONFLICT (game_id, language_code) DO NOTHING;
