INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Academy: Lessons for Everyone!', 'Art Academy: Lessons for Everyone! is an interactive application that teaches real world art techniques anyone can enjoy-from beginners to experts of all ages. Discover more than 30 lessons, all using realistic stylus and touch screen-based tools for drawing and painting. Enjoy a robust Free Paint mode that lets you create to your heart''s content using included subjects, or your own images taken with the Nintendo 3DS Camera—whenever and wherever the inspiration strikes.' FROM games WHERE igdb_id = 6849 ON CONFLICT (game_id, language_code) DO NOTHING;
