INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trick-or-treat-training', 175222, '2012-10-18', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sce4iy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trick or Treat Training', 'From Astro Crow - the creators of the hit iPhone game The Last Ace of Space! Are you as excited about Halloween as we are? All the costumes, the scares, and best of all- the CANDY!! We know that handing out candy all night long can be tough, so that''s why we''ve invented Trick or Treat Training! In this game- the first ever Halloween candy-handing-out simulator EVER- we''ve put YOU in charge of handing out candy to all the neighborhood kids. When you answer the door, quickly flick the candy that they are thinking about to them. But be quick- these kids change their mind fast! How high of a score can you get before your time runs out?' FROM games WHERE igdb_id = 175222 ON CONFLICT (game_id, language_code) DO NOTHING;
