INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melon Journey', '"The cult classic RPG maker game that launched our careers  Made in just a week back in 2012  In this game you choose to play as either Cantaloupe (Melon Boy) or Honeydew (Melon Girl)  You find yourself in the outskirts of Hog Town, with your buddy nowhere to be seen. Ask around and see if any of the hedgehogs, hamsters, cats or dogs have any valuable info (but it may not come easy).  Full of inside jokes, Melon Journey sometimes doesn''t make much sense but it was made with a lot of love for all our friends and the people we admire."' FROM games WHERE igdb_id = 132112 ON CONFLICT (game_id, language_code) DO NOTHING;
