INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killer-bean-unleashed', 262652, '2012-03-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6z3n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq1sl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Bean Unleashed', 'Killer Bean Unleashed delves into the relentless journey of Killer Bean, a former elite assassin who finds himself at odds with the organization that once employed him. This high-octane action platformer showcases a fusion of classic gameplay dynamics with cutting-edge visuals. As players navigate through 29 challenging levels, they''ll encounter a myriad of adversaries from the Shadow Agency. To truly dominate the game, one needs not only skill but also a range of super weapons – from Magnum bullets and Explosive rounds to Beam Splitter Lasers and Fire Bombs. In this adrenaline-pumping quest for vengeance, unique features like triple jumps bring an almost ethereal feel to the experience, while recent updates introduce daily dungeon levels, enhanced aiming assistance, and a range of interactive in-game elements.' FROM games WHERE igdb_id = 262652 ON CONFLICT (game_id, language_code) DO NOTHING;
