INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Labyrinth of Grisaia', 'The Labyrinth of Grisaia is a Japanese adult visual novel, the second in a series of visual novels by Front Wing and the sequel to The Fruit of Grisaia. It contains five "After Stories" continuing all of the heroines'' routes from the first game in addition to "The Cocoon of Caprice," a story which touches on Kazami Yuji''s painful, complex past and explores certain mysteries left unresolved in the previous title.' FROM games WHERE igdb_id = 11457 ON CONFLICT (game_id, language_code) DO NOTHING;
