INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-simpsons-tapped-out', 2845, '2012-02-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jg2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1s25.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Tapped Out', 'The Simpsons: Tapped Out is a freemium mobile game for iOS and Android, based on the American animated series The Simpsons. It allows users to create and maintain their own version of Springfield using familiar characters and buildings. The game is constantly being updated with new, often season-specific content, for example during holidays like Thanksgiving, and Treehouse of Horror episodes-related content for Halloween. Not limited to English-speaking players, the game is available in many languages such as French, Italian, German, Simplified Chinese and Brazilian Portuguese. The game was developed and published by EA Mobile and launched in the EU on February 29, 2012 and in US on March 1, 2012 for iOS and February 6, 2013 for Android. The game was released for Kindle Fire devices in several markets on June 24, 2013. According to its own estimates, EA generated over $130 million in revenue since the game''s release. For BlackBerry 10, the Android version of the game can be downloaded via Amazon Appstore.' FROM games WHERE igdb_id = 2845 ON CONFLICT (game_id, language_code) DO NOTHING;
