INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umbra', 'Umbra is a Yume Nikki fangame. It stars Scott, a boy who gets trapped inside his home due to a storm. The main focus of the game is exploring his dream world. Umbra is the first game to use talk sprites, as well as the first to make dialogue an important gameplay element. The gameplay is traditional where the player is collecting effects, but with more puzzles and having dialogue choices affect the game.' FROM games WHERE igdb_id = 202338 ON CONFLICT (game_id, language_code) DO NOTHING;
