INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legends of War: Patton', 'In this epic turn-based strategy game you will follow the paths of General Patton during WWII, leading your troops to battle while traversing Western Europe''s devastated land. Gain prestige points and use them to enhance your army, acquiring advanced weapons and gear. Play through four different types of missions: Attack, Defense, Infiltration, and Sabotage. From the French beaches to Belgium, you will have to prove your worth as a member of Patton''s Third Army, and fight for victory!' FROM games WHERE igdb_id = 20015 ON CONFLICT (game_id, language_code) DO NOTHING;
