INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'More Donuts! by Maverick', 'You get to mix up your dough and cut out donuts, donut holes, filled donuts or even bars. Then drop them in the fryer til they are a golden brown. After you’ve made a batch, you can decorate each donut just like you want, painting on icing, sprinkles, candy, fruit, nuts and more! Finally, eat your donuts by taking virtual bites, or share them with friends on Facebook or via email. Yeast donuts, cake donuts, cinnamon rolls, chocolate cake, blueberry cake, and buttermilk donuts are all in there! Make each from scratch with real recipes.' FROM games WHERE igdb_id = 108714 ON CONFLICT (game_id, language_code) DO NOTHING;
