INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starhawk', 7461, '2012-05-08', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4903.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fx1jk28jmlpjmxnmcbdi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starhawk', 'In the far reaches of space, factions of humanity battle over a rare and dangerous resource known as Rift Energy. Colonies of humans called Rifters have been exploring the "Frontier" of planets, but find their way of life threatened by the Outcast, a ruthless species of humans who have mutated into psychotic monsters due to exposure to this very same Rift Energy. Caught in the middle is Emmett Graves, a hired gunslinger ostracized from society because of his own exposure to Rift Energy, leaving him partially mutated, but still able to retain his humanity. Graves is drawn back to his home settlement to face a mysterious outlaw and his war band of Outcast warriors. Starhawk provides fast paced third-person shooter action set in this lawless frontier of space, allowing players to instantly alter the battlefield by calling down offensive and defensive structures in real-time from an orbiting drop ship, all while blasting away at enemies in the middle of huge single-player or multi-player firefights.' FROM games WHERE igdb_id = 7461 ON CONFLICT (game_id, language_code) DO NOTHING;
