INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talesworth Adventure: The Lost Artifacts', 'Questy the Adventurer, a talented fantasy barbarian, has blown through the last of his loot and needs to get his cash flow moving again. Now Boneyard the Necromancer threatens the land from his lair beyond the mountains, guarded by a magical statue requiring three scattered artifacts to be reunited in order to pass through, save the kingdom -- and get paid again. Is the player up to managing this quest?' FROM games WHERE igdb_id = 111550 ON CONFLICT (game_id, language_code) DO NOTHING;
