INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('picdun-2-witchs-curse', 47646, '2012-08-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gtttevq5f5xqjpemuqvg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1i0i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Picdun 2: Witch''s Curse', 'Picdun 2: Witch''s Curse is a 3D dungeon RPG set in the mysterious dungeon called "Picdun." Choose your partner from three female adventurers--the Archer, the Whipper and the Spellcaster--and venture into the depths of the dungeon together. Sixty stages await you, filled with a wide variety of puzzles ranging from easy to mind-bendingly difficult!  Places you go are mapped automatically, and once you cover all the tiles on a floor you will complete the picture hidden underneath.  As in the previous game, battles feature a large number of dynamic and powerful enemies. The hero is unable to attack due to the Witch''s Curse, so he must protect his partner with a shield and guide her to attack by chopping down or slashing sideways. Also, you can trigger a power move by raising the shield at the same time as an enemy attack.  Explore the depths of the dungeon to uncover the mystery of the Witch''s Curse!' FROM games WHERE igdb_id = 47646 ON CONFLICT (game_id, language_code) DO NOTHING;
