INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 125276 AND rs.code = 'PEGI' AND r.code = '16' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 125276 AND rs.code = 'ESRB' AND r.code = 'M' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', false, true, true FROM games WHERE igdb_id = 125276 ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'ja', 'Japanese', false, true, true FROM games WHERE igdb_id = 125276 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('poptropica-adventures', 47928, '2012-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x7ifr7pqbpd2eflqsqag.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poptropica Adventures', 'The Poptropica museum is in ruins and needs your help! Explore three amazing islands and find missing artifacts to help restore the museum to its former glory. Meet interesting characters, collect artifacts, solve puzzles and play mini games in the ultimate on-the-go Poptropica experience!! Looking to stand out in a crowd? Customize the look of your avatar with new clothes, hats, hair styles and more and show off your own unique Poptropica style! Features: • Run and jump through three amazing Poptropica islands • Collect items and rebuild the Poptropica museum! • Complete the quests and unlock a host of minigames • Customize your avatar with new clothes, hats, hair styles and more' FROM games WHERE igdb_id = 47928 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 47928 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 47928 AND c.slug = 'other-ocean-interactive' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 47928 AND c.slug = 'ubisoft-entertainment' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 47928 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;